(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-pd-disaggregation-moe"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-1\">一 · 事故现场：一次混部集群的 SLO 雪崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-2\">二 · 它到底解决什么：把零和博弈变成两笔独立账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-3\">三 · 两池配比：吞吐方程与比例失配的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-4\">四 · 它不解决什么：三条清晰的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-5\">五 · 适用边界的工程判断：什么条件下值得拆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-6\">六 · 边界不在“能不能拆”，而在“拆完还划不划算”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-7\">七 · 拆开之后谁在付账：比例失配、RDMA 传输与格式重排的三重边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-8\">八 · 请求入池：prefill 侧的输入整形与 TP 切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-9\">九 · KV 打包：层/页粒度与格式对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-10\">十 · RDMA 跨池传输：带宽账与流水重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-11\">十一 · decode 池接收：EP 布局落地与本地索引</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-12\">十二 · 连续批处理生成：原地追加与释放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-13\">十三 · 两池配比：吞吐方程与失配的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-14\">十四 · 跨池 KV 搬运与静态配比：分离部署真正付费的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-15\">十五 · Goodput 目标函数与两阶段约束的耦合项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-16\">十六 · 两池配比的吞吐方程与失配代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-17\">十七 · KV 打包格式与 EP 布局对齐的推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-18\">十八 · 流水重叠的伪代码与可实现性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-19\">十九 · 量化方案独立选择对公式系数的影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-20\">二十 · 从公式到工程判断：何时分离、何时不分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-21\">二十一 · 请求形态的筛选：什么样的负载才配得上分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-22\">二十二 · 长度分布与批大小的耦合：decode 池的 batch 是被输入喂出来的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-23\">二十三 · 并发与配比：静态比例在什么流量下成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-24\">二十四 · 负载不对时的三种失败形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-25\">二十五 · 把负载配方写进部署参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-26\">二十六 · 负载配方：长上下文在线服务是它的主场，错配流量是它的死穴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-27\">二十七 · 硬件档位与两池的物理边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-28\">二十八 · 并行拓扑：prefill 用 TP、decode 用 EP 的不可交换性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-29\">二十九 · 量化方案：两池独立选择及其对传输量的连带影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-30\">三十 · KV 策略：打包粒度、流水重叠与释放时机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-31\">三十一 · 调度参数与两池配比的可复现配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-32\">三十二 · 比例失配与 RDMA 传输：这套配方的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-33\">三十三 · 显存账：两池各自的第一道墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-34\">三十四 · 带宽账：RDMA 传输量与重叠窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-35\">三十五 · 通信账：EP 布局接收与 all-to-all 的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-36\">三十六 · 功耗与配比：静态比例在突发流量下的崩塌</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-37\">三十七 · 尾延迟：三个先崩点的排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-38\">三十八 · 规模上限的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-39\">三十九 · 规模上去先崩在哪：RDMA 带宽、两池配比与尾延迟的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-40\">四十 · 精度漂移：跨池量化不一致与 KV 数值路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-41\">四十一 · OOM 的三条路径：KV 池、专家权重与传输缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-42\">四十二 · 批抖动与路由不均：两个不同源的尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-43\">四十三 · 尾延迟尖刺：RDMA 传输与重排的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-44\">四十四 · 监控面与回滚：把两池当一条链路来观测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-45\">四十五 · 失效边界：比例失配、传输主导与布局重排</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-46\">四十六 · 对照轴：三条正交的取舍线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-47\">四十七 · 决策表：五种形态的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-48\">四十八 · 配比方程与选型的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-49\">四十九 · 与量化、路由类算法的组合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-50\">五十 · 规模上限与退回路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-51\">五十一 · 何时不该拆：物理分离的失效边界与选型决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disaggregation-moe-sec-52\">五十二 · 同族对照下的选型判据与失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求先进入 prefill 池，按 TP 并行计算并生成 KV</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">KV 按层/页打包，经 RDMA 写入 decode 池的 KV 存储</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">decode 池按 EP 布局接收 KV，router 与专家在本地 ra…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">decode 池连续批处理生成 token，KV 原地追加</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">完成后释放 KV，请求返回客户端</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-pd-disaggregation-moe-sec-1\">一 · 事故现场：一次混部集群的 SLO 雪崩</h3>\n<p>某长上下文在线服务在单一 GPU 池上同时跑 prefill 与 decode，模型是带专家并行的 MoE。上线初期流量平稳，TTFT 与 TPOT 都贴着 SLO 红线但尚能达标。一次上游业务推送导致请求形态突变：长上下文请求占比骤升，prefill 阶段的计算量按上下文长度线性放大，而 decode 阶段因为并发请求数增加、batch 变大，对显存带宽与专家权重的读取压力同步上升。两类负载在同一批 SM 上争抢资源，调度器无法同时满足两个约束——prefill 的算力被 decode 的常驻 batch 切走，TTFT 迅速超标；而为了压 TTFT 临时提高 prefill 优先级，又把 decode 的 token 间隔拉长，TPOT 跟着破线。最终表现是：GPU 利用率看起来不低，但满足 SLO 的请求数急剧下降，Goodput 塌陷。</p>\n<div class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$</div>\n<p>这起事故的根因不是某个算子慢，而是两种阶段的资源画像根本对立：prefill 是计算密集，吃满 tensor core 与高带宽的权重读取；decode 是带宽密集，每个 token 都要把巨量专家权重从 HBM 搬一遍，算力反而闲置。混部时任何一次优先级调整都是在两个 SLO 之间做零和博弈，而 MoE 的专家并行把矛盾进一步放大——prefill 阶段希望用大 TP 把单次前向的算力打满，decode 阶段希望用 EP 承载大 batch 以提升专家利用率，两套最优并行布局在同一组 GPU 上无法共存，router 与专家的放置被迫折中，两边都不讨好。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-2\">二 · 它到底解决什么：把零和博弈变成两笔独立账</h3>\n<p>预填解码分离部署的核心动作是物理拆分：把 prefill 与 decode 放到不同的 GPU 池，让两个阶段各自使用自己的最优并行策略，从而把「TTFT 与 TPOT 二选一」的零和问题拆成两笔可以分别核算的账。prefill 池用大 TP 打满算力，按 TTFT SLO 配置 TP 度；decode 池用 EP 承载大 batch，按 TPOT SLO 配置 EP 度与批大小。两个池的 SLO 约束解耦后，TTFT 只由 prefill 池的算力与排队决定，TPOT 只由 decode 池的带宽与 batch 稳定性决定，不再互相踩踏。</p>\n<p>数据流按顺序是：请求先进入 prefill 池，按 TP 并行计算并生成 KV；KV 按层/页打包，经 RDMA 写入 decode 池的 KV 存储；decode 池按 EP 布局接收 KV，router 与专家在本地 rank；decode 池连续批处理生成 token，KV 原地追加；完成后释放 KV，请求返回客户端。这里的关键机制是 KV 的跨池搬运被显式建模为一次数据传输，而不是混部时隐式的资源竞争——传输量、传输时间、与 decode 计算的流水重叠都成为可观测、可调度的对象。</p>\n<p>代价同样明确：KV 跨池传输占用 RDMA 带宽，长上下文时传输时间不可忽略；两池比例需按流量预测静态配置，突发流量下易出现一侧空闲一侧过载。这两条代价决定了它的适用边界，而不是它的优点清单。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-3\">三 · 两池配比：吞吐方程与比例失配的代价</h3>\n<p>拆分之后，工程上第一个要回答的问题是两池各放多少 GPU。可按吞吐方程估算：</p>\n<div class=\"formula\">$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</div>\n<p>其中 $N_p$、$N_d$ 为两池 GPU 数，$R_{\\text{prefill}}$、$R_{\\text{decode}}$ 为两阶段单位时间请求处理能力。这个式子不是精确解，而是一个配比基线：它把「两阶段处理能力之比」翻译成「GPU 数量之比」，让容量规划从拍脑袋变成可核算的除法。比例失配的后果是单向的——prefill 池偏小则请求在 prefill 侧排队，TTFT 超标而 decode 池 GPU 空闲；decode 池偏小则 KV 到达后无法及时消费，TPOT 抖动而 prefill 池算力闲置。两种失配都让整体吞吐与 SLO 同时恶化，且因为配比是静态的，突发流量下几乎必然出现某一侧的瞬时过载。</p>\n<p>以一个具体场景说明代价的量级关系：长上下文请求的 KV 体积随上下文长度与层数增长，跨池 RDMA 传输时间与 KV 字节数成正比、与可用 RDMA 带宽成反比。当传输时间与 decode 计算未充分重叠时，TTFT 会被传输主导——prefill 算完了，但首 token 迟迟出不来，因为 KV 还在路上。这就是为什么分离部署必须把「KV 传输与 decode 计算流水重叠」当作一等公民来设计，而不是事后优化。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-4\">四 · 它不解决什么：三条清晰的边界</h3>\n<p>第一，它不解决单池内部的并行策略选择问题。分离部署只是把两阶段分开，prefill 池内部用什么 TP 度、decode 池内部用什么 EP 度与 batch 策略，仍需各自独立设计；拆分本身不产生算力，只消除争抢。第二，它不解决 KV 打包格式与本地专家分片不一致带来的重排开销——decode 池按 EP 布局接收 KV 时，若层/页打包格式与本地专家分片不匹配，需要额外重排，增加显存拷贝与延迟，这是分离部署引入的新失败模式，而非它治愈的旧病。第三，它不解决低负载场景的经济性：当流量不足以让两个池都跑满时，物理分离意味着两侧都可能低利用率，此时混部的资源复用反而更划算。分离部署的收益随负载升高而放大，随负载降低而收缩。</p>\n<p>还有一条边界值得单独点出：规模上限受 RDMA 带宽与 KV 传输量制约。上下文越长、层数越多，跨池传输越成为瓶颈，分离部署的净收益被传输开销侵蚀。这不是可以靠调参绕过的，而是拓扑层面的硬约束——它决定了这套方法适合高负载、长上下文、TTFT 与 TPOT 双 SLO 严格的集群部署，而不适合小规模、短上下文、SLO 宽松的推理服务。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-5\">五 · 适用边界的工程判断：什么条件下值得拆</h3>\n<p>把上述边界收拢成可操作的判断标准，可以按三个维度过一遍。其一是负载水平：只有当混部时两个 SLO 已经无法同时满足、且 GPU 利用率显示资源被争抢而非闲置时，拆分才有正收益；若混部下 Goodput 仍贴着 SLO 达标，拆分引入的 RDMA 开销与配比管理复杂度就是净负债。其二是上下文长度：KV 传输量随上下文增长，传输时间与 decode 计算的重叠窗口是否足够，决定了拆分后 TTFT 是否真的改善；长上下文场景必须先把传输流水设计好，否则拆分只是把排队从 SM 上搬到了 RDMA 链路上。其三是 SLO 严格度：TTFT 与 TPOT 双约束越紧，混部的零和博弈越激烈，分离部署的解耦价值越大；SLO 宽松时，混部的资源复用优势反而更明显。</p>\n<p>一个具体的工程判断落点是：先按吞吐方程算出配比基线，再按流量预测留缓冲，把「突发流量下比例失配」当作已知失败模式纳入容量规划，而不是指望静态配比在任意流量下都成立。分离部署不是一次性的架构决策，而是一个需要持续按流量配方校准配比的运行态系统——它的稳定性来自对比例失配的主动管理，而非拆分动作本身。</p>\n<p>最后落在机制上：这套方法的本质是把「两种资源画像对立的阶段」从时间维度上的争抢，转换为空间维度上的分工，并用 RDMA 上的 KV 搬运把两者重新缝合。缝合处的带宽预算与两池配比，就是这套方法全部工程风险的所在——拆分本身不难，难的是让缝合处的传输开销始终小于解耦带来的 SLO 收益。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-6\">六 · 边界不在“能不能拆”，而在“拆完还划不划算”</h3>\n<p>先说一个线上事故的形态：集群按预测流量把 GPU 切成 prefill 池与 decode 池，比例写死在调度器里。某天上游一个批量任务把长上下文请求集中打进来，prefill 池瞬间打满、TTFT 迅速越过 SLO，而 decode 池因为拿不到新请求的 KV，batch 掉到很低、专家利用率塌陷，GPU 大量空转。运维的第一反应是“扩容”，但扩容只能加在某一侧，另一侧依旧闲置——这正是本方案最典型的失效条件：<strong>它不是弹性架构，而是一个按吞吐方程静态配比的流水线</strong>。配比估算写成 <div class=\"formula\">$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</div> 其中 $N_p$、$N_d$ 为两池 GPU 数，$R$ 为两阶段单位时间请求处理能力。这个式子只在流量配方稳定时成立；一旦请求长度分布漂移，$R_{\\text{prefill}}$ 与 $R_{\\text{decode}}$ 的相对关系就变了，比例失配立刻表现为一侧过载、一侧空闲，整体 Goodput 与双 SLO 同时恶化，而不是简单地“慢一点”。</p>\n<p>第二个边界是 RDMA 传输量。KV 按层/页打包从 prefill 池写入 decode 池的 KV 存储，这笔开销随上下文长度与层数线性增长，而 decode 侧的计算量只随 batch 增长。于是存在一个临界上下文长度：超过它，跨池传输时间开始主导 TTFT，即使 prefill 计算本身很快也无济于事。工程上要判断的是传输与 decode 计算是否真正流水重叠——若 KV 到达一页才能起算一页，重叠度就差；若按层流水、decode 侧边收边算，传输可以藏在计算背后。这条判断比“带宽够不够”更关键，因为带宽是常量，重叠度是设计选择。规模上限因此不由 GPU 数决定，而由 RDMA 带宽与 KV 传输量之比决定：上下文越长、层数越多，跨池传输越是瓶颈，此时把两阶段放回同一池、用分块预填捎带反而更省。</p>\n<p>第三个边界是格式一致性。decode 池按 EP 布局接收 KV，router 与专家在本地 rank；如果 prefill 侧按 TP 切分产生的层/页打包格式与 decode 侧本地专家分片不一致，接收端必须额外重排，带来显存拷贝与延迟，且这部分开销不体现在任何“计算”指标里，只体现在 TPOT 的尾部。这也是 MoE 特有的代价：稠密模型两池的 KV 布局只差一个切分维度，MoE 还多一层专家归属，重排逻辑写错就会静默地拖慢长尾。</p>\n<p>那么它不解决什么？它不解决单请求内部的算力瓶颈，不解决专家负载倾斜（EP 布局下热门专家仍会排队），也不提供突发流量的自动伸缩——两池比例是管理复杂度换来的确定性。适用面因此收窄到：高负载、长上下文、TTFT 与 TPOT 双 SLO 严格、流量配方可预测的集群部署。反过来，低负载时拆分的收益被传输开销吃掉；上下文短到 KV 传输可忽略时，混部争抢本就不严重；流量配方剧烈波动时，静态配比的管理成本高于收益。判断标准可以落到一个可测的量上：<div class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$</div> 把跨池传输的 GPU 秒与重排的显存拷贝都计入分母，若拆分后的 Goodput 不高于混部加分块预填，就不该拆——这是本方案唯一诚实的准入条件。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-7\">七 · 拆开之后谁在付账：比例失配、RDMA 传输与格式重排的三重边界</h3>\n<p>分离部署把 TTFT 与 TPOT 从互相拉扯变成各自独立约束，但它并不消除资源竞争，只是把竞争从卡内搬到了池间。真正的失效点有三类。第一类是配比失配：两池 GPU 数按吞吐方程 <span class=\"formula\">$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</span> 静态配置，而 $R_{\\text{prefill}}$、$R_{\\text{decode}}$ 随请求长度分布漂移。突发长上下文涌入时 prefill 池排队、TTFT 超标，decode 池却因拿不到新 KV 而空转；反向突发短请求时 decode 池 batch 堆满、TPOT 抖动，prefill 池闲置。此时 Goodput 按 <span class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}}$$</span> 同时被分子和分母惩罚——这是分离式最典型的线上事故形态，而非单点故障。</p>\n<p>第二类是跨池 KV 传输。KV 按层/页打包经 RDMA 从 prefill 池写入 decode 池，传输量随上下文长度与层数线性增长，而 RDMA 带宽是固定预算。当传输时间与 decode 计算未充分流水重叠时，TTFT 由传输主导而非计算主导，分离带来的收益被抵消。适用边界因此写得很硬：规模上限受 RDMA 带宽与 KV 传输量制约，上下文越长、层数越多，跨池传输越成为瓶颈。长上下文在线服务若不做传输/计算重叠，等于把 prefill 省下的时间又还给网络。</p>\n<p>第三类是布局不一致的隐性代价。decode 池按 EP 布局接收 KV，router 与专家在本地 rank；若层/页打包格式与本地专家分片不匹配，需额外重排，产生显存拷贝与延迟，且这部分开销不体现在任何 SLO 公式里。它与分块预填捎带的差别也在此：物理分离换来各自最优并行策略与大而稳定的 decode batch，代价是 RDMA 带宽开销与两池静态配比的管理复杂度。判断是否采用，看三条：TTFT 与 TPOT 是否双 SLO 严格、负载是否高且长上下文为主、集群 RDMA 带宽是否足以覆盖 KV 传输峰值；任一不满足，混部加分块预填反而是更稳的选择。</p>\n<h3 id=\"alg-pd-disaggregation-moe-sec-8\">八 · 请求入池：prefill 侧的输入整形与 TP 切分</h3>\n<p>一个请求进入分离式部署时，第一步不是立刻算 attention，而是被 prefill 池的调度器整形。输入是原始 prompt token 序列、采样参数、以及该请求的 SLO 标签（TTFT 上限、TPOT 上限）。调度器要做的决策是：这个请求分给哪一组 TP rank、是否与同批其他请求拼成一条更长的序列、以及分块预填的 chunk 大小。输出是一份「已绑定并行组」的计算任务，附带一个后续 KV 传输所需的元数据头（层数、每层 KV 页数、页表基址、目标 decode 池标识）。</p>\n<p>代价在这里第一次显形：TP 度越大，单请求的 prefill 算力越足，但每增加一档 TP，就要多一次 all-reduce 的通信步，且 KV 在 TP 组内是按 head 切分的——这意味着同一请求的 KV 在物理上分散在多个 rank 的显存里。以长上下文在线服务为例，prompt 长度达到数万 token 时，prefill 池按 TTFT SLO 配置 TP 度，把单请求的首 token 时延压进预算；但 TP 组内每个 rank 只持有自己那几个 head 的 KV 分片，后续打包必须按「层 × 页 × head 分片」的粒度做，否则 decode 池无法按 EP 布局还原。这一步的吞吐代价是 TP 通信开销随度线性增长，显存代价是 KV 分片分散导致打包时需要跨 rank 汇聚。</p>\n<div class=\"formula\">$$\\text{TTFT}_{\\text{prefill}} \\approx \\frac{C_{\\text{prompt}}}{F_{\\text{TP}}\\cdot \\eta_{\\text{compute}}} + T_{\\text{comm}}(d_{\\text{TP}}) + T_{\\text{pack}}$$</div>\n<p>其中 $C_{\\text{prompt}}$ 是 prompt 的计算量，$F_{\\text{TP}}$ 是单卡算力，$T_{\\text{comm}}$ 是 TP 组通信时间，$T_{\\text{pack}}$ 是 KV 打包时间。工程判断是：$T_{\\text{pack}}$ 必须与 attention 计算流水重叠，否则它会直接吃掉 TTFT 预算——这也是为什么打包格式要在 prefill 计算过程中就按页对齐生成，而不是等全部层算完再统一整理。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-9\">九 · KV 打包：层/页粒度与格式对齐</h3>\n<p>prefill 算完后，KV 不是一整块连续内存，而是按层分布、每层内按页（paged KV）组织、页内再按 head 分片。打包步骤的输入是这些分散的 KV 张量，输出是一串可被 RDMA 直接寻址的传输描述符：每个描述符对应一层的一个页，携带源地址、目标地址、字节数、以及一个格式标签。</p>\n<p>这里的核心机制是「格式标签必须与 decode 池的 EP 布局对齐」。decode 池按 EP 切分专家，router 与专家都在本地 rank，但 attention 的 KV 是按 head 组织的——如果 prefill 池的 TP 切分把 head 切成了 8 份，而 decode 池的 EP 布局期望的是另一种 head 分组，那么 KV 到达后需要额外重排。重排意味着显存拷贝：一份 KV 从接收缓冲区拷到目标页表位置，再按专家分片重新索引。这个拷贝的代价是显存带宽，在长上下文、多层模型下会累积成可观的延迟。</p>\n<p>具体例子：一个 60 层左右的 MoE 模型，每层 KV 页数随上下文线性增长。若 prefill 池 TP=8、decode 池 EP=16，head 分组在两个池里天然不同，打包时必须按 decode 池的 head 分组重排页内布局，而不是简单地把 TP rank 的本地 KV 原样发出。代价量化：每层每页一次重排拷贝，总拷贝量正比于「层数 × 页数 × 页大小」，这部分带宽开销与 RDMA 传输带宽是两笔独立的账。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-10\">十 · RDMA 跨池传输：带宽账与流水重叠</h3>\n<p>传输步骤的输入是打包好的描述符列表，输出是 decode 池接收缓冲区里落地的 KV。机制上是按页发起的 RDMA write，源端 prefill 池的网卡直接写目标端 decode 池的显存，不经过两端 CPU。这一步的代价是纯带宽：传输时间正比于 KV 总字节数除以有效 RDMA 带宽。</p>\n<div class=\"formula\">$$T_{\\text{xfer}} = \\frac{S_{\\text{KV}}}{B_{\\text{RDMA}}\\cdot \\eta_{\\text{link}}},\\quad S_{\\text{KV}} \\propto L_{\\text{ctx}}\\cdot n_{\\text{layer}}\\cdot d_{\\text{head}}\\cdot n_{\\text{head}}$$</div>\n<p>关键工程点是流水重叠：KV 按层打包，就可以按层发起传输，让第 $i$ 层的传输与第 $i+1$ 层的 prefill 计算重叠，也让 decode 池在第 $i$ 层 KV 到达后即可开始该层的 decode 计算，而不必等全部层传完。若不做重叠，长上下文请求的 $T_{\\text{xfer}}$ 会直接主导 TTFT——上下文越长、层数越多，跨池传输越是瓶颈，这正是该架构的规模上限所在。</p>\n<p>具体例子：长上下文在线服务中，一个请求的 KV 总量随上下文线性膨胀，若 RDMA 带宽被多个并发请求的 KV 传输共享，单请求的有效带宽下降，$T_{\\text{xfer}}$ 上升。此时 TTFT 的构成从「计算主导」变成「传输主导」，SLO 超标。工程对策是把传输按层切成小片、与 decode 计算交错，并给传输留出带宽缓冲，而不是等整请求 KV 全部落地再启动 decode。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-11\">十一 · decode 池接收：EP 布局落地与本地索引</h3>\n<p>decode 池接收 KV 的输入是 RDMA 落地的页数据与格式标签，输出是一份「已挂到本地页表、按 EP 分片索引」的 KV 视图。机制上，decode 池的每个 rank 只持有自己负责的专家分片，router 在本地 rank 上运行，因此它需要的是「按专家分片可寻址」的 KV 索引，而不是按 TP head 分片的原始布局。接收步骤要把格式标签翻译成本地页表项，必要时做一次重排拷贝。</p>\n<p>代价有两层：第一层是显存，接收缓冲区与目标页表是两份显存，重排期间 KV 短暂双份存在；第二层是延迟，重排拷贝占用显存带宽，与 decode 的连续批处理争抢同一份带宽资源。工程上应尽量让打包格式在源头就对齐 decode 池的 EP 布局，把重排降为零拷贝的页表重映射——这要求 prefill 池在打包时就知道 decode 池的专家分片方案，两池的布局协商是部署期的一次性配置，而不是运行期的动态转换。</p>\n<p>具体例子：decode 池按 TPOT SLO 配置 EP 度与大 batch，EP 度越大，单 rank 持有的专家越少，KV 索引的粒度越细，重排的复杂度越高。若层/页打包格式与本地专家分片不一致，额外重排带来的显存拷贝与延迟会直接反映在 TPOT 上，因为 decode 是逐 token 的带宽密集阶段，任何额外的显存流量都是纯开销。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-12\">十二 · 连续批处理生成：原地追加与释放</h3>\n<p>decode 池的核心循环是连续批处理：输入是已挂载 KV 的活跃请求集合，输出是每个请求新生成的 token 及其追加后的 KV。机制上，每步只为活跃请求算一个 token，新 token 的 KV 原地追加到该请求已分配的页里，页满则从空闲页池取新页挂到页表尾部。batch 的大小由 decode 池的显存与 EP 布局决定，batch 越大，专家利用率越高，但单步延迟也随 batch 增长。</p>\n<div class=\"formula\">$$\\text{TPOT} \\approx \\frac{W_{\\text{decode}}(B)}{B\\cdot F_{\\text{EP}}} + T_{\\text{append}},\\quad \\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}}$$</div>\n<p>其中 $W_{\\text{decode}}(B)$ 是 batch 为 $B$ 时单步的显存流量（权重读取加 KV 读写），$F_{\\text{EP}}$ 是 EP 组的有效带宽。这里的关键判断是：decode 池的 batch 大而稳定，是因为它不掺 prefill 的计算尖峰，专家利用率得以维持在高位——这正是分离部署换来的收益。代价是原地追加的页管理：页满换页、页表更新都是显存写操作，在长上下文请求上累积成可观的带宽开销。</p>\n<p>请求完成时，释放步骤回收该请求占用的全部 KV 页，归还空闲页池，请求返回客户端。释放本身很轻，但页池碎片化是隐性代价：长短请求混合时，页池被切成不同大小的碎片，大 batch 需要连续页时可能找不到足够空间，调度器不得不降低 batch 或触发页整理。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-13\">十三 · 两池配比：吞吐方程与失配的代价</h3>\n<p>整条流水线的稳态由两池的 GPU 数配比决定。输入是流量预测给出的两阶段单位时间请求处理能力，输出是 $N_p/N_d$ 的静态配置值。机制上按吞吐方程估算：</p>\n<div class=\"formula\">$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</div>\n<p>其中 $R_{\\text{prefill}}$ 由 TTFT SLO 下的 TP 度与单卡算力决定，$R_{\\text{decode}}$ 由 TPOT SLO 下的 EP 度与 batch 决定。比例失配即出现一侧空闲一侧过载：prefill 池偏小则请求排队、TTFT 超标；decode 池偏小则 batch 被迫缩小、专家利用率下降、TPOT 恶化。失败模式是突发流量下预测失效——静态配比无法跟随瞬时负载，一侧 GPU 空闲而另一侧过载，整体吞吐与 SLO 同时恶化。</p>\n<p>工程判断落在缓冲与流水两点：配比要留缓冲吸收预测误差，KV 传输要与 decode 计算充分重叠以压低传输对 TTFT 的贡献。长上下文请求是这套配比最脆弱的场景——它的 KV 传输量最大、$T_{\\text{xfer}}$ 最不可忽略，若与 decode 计算未重叠，TTFT 被传输主导，此时再大的 prefill 算力也救不回来。因此配比估算必须把 RDMA 带宽作为独立约束纳入，而不是只算两阶段的计算能力。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-14\">十四 · 跨池 KV 搬运与静态配比：分离部署真正付费的地方</h3>\n<p>物理分离之后，请求路径上多出一段原本不存在的环节：KV 从 prefill 池的 TP 分片布局，变成 decode 池的 EP 分片布局。prefill 侧按 TP 切分时，每层 KV 头被均匀分到各 rank；decode 侧按 EP 切分时，注意力头与 KV 页要落到持有对应 router 与专家的本地 rank 上。因此打包不能只按“页”做，必须按“层 × 页 × 目标 rank”三元组组织，使接收端无需再做全局重排。若格式不一致，decode 池要先做一次显存内的 gather/scatter 重排，代价是额外的 HBM 读写与一次同步屏障——在 decode 这种每 token 都要走一遍的路径上，这笔拷贝会直接体现在 TPOT 上，而不是只影响首 token。</p>\n<p>传输时间可以写成可核算的形式：设单请求 KV 总量为 $S_{\\text{kv}}$（随上下文长度与层数线性增长），跨池有效带宽为 $B_{\\text{rdma}}$，重叠窗口为 $W$，则 KV 阶段对 TTFT 的净贡献近似为</p>\n<div class=\"formula\">$$T_{\\text{kv}}=\\max\\left(0,\\ \\frac{S_{\\text{kv}}}{B_{\\text{rdma}}}-W\\right)$$</div>\n<p>当 $S_{\\text{kv}}/B_{\\text{rdma}}$ 小于 prefill 计算尾段可重叠的窗口时，传输被完全隐藏，TTFT 由算力决定；一旦长上下文把 $S_{\\text{kv}}$ 推高，$T_{\\text{kv}}$ 转为正值并线性增长，TTFT 被 RDMA 主导。这就是适用边界：规模上限不由 GPU 算力决定，而由 RDMA 带宽与 KV 传输量共同决定。工程上应把“KV 字节数 / 有效带宽”作为容量规划的一等指标，与算力、显存并列核算，并在长上下文占比升高时优先扩带宽而非扩算力。</p>\n<p>第二个代价是配比。两池 GPU 数按吞吐方程估算：</p>\n<div class=\"formula\">$$\\frac{N_p}{N_d}\\approx\\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</div>\n<p>其中 $R_{\\text{prefill}}$、$R_{\\text{decode}}$ 是两阶段单位时间请求处理能力，二者对上下文长度、batch 大小、量化位宽的敏感度不同——prefill 随上下文近似线性变慢，decode 随 batch 增大而边际摊薄。这意味着同一个静态比例只在某一负载配方下成立；突发流量或上下文分布漂移时，比例失配立刻表现为一侧 GPU 空闲、另一侧排队，整体 Goodput 与双 SLO 同时恶化。可用缓冲吸收短时抖动，但缓冲本身是闲置资源，直接压低 $\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}}$。判断标准很具体：若观测到 prefill 池利用率长期低于 decode 池排队深度对应的水平，说明 $N_p$ 偏大，应把 GPU 迁往 decode 侧，而不是加大缓冲。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测信号</th><th>系统代价落点</th></tr></thead><tbody><tr><td>长上下文 KV 传输未重叠</td><td>TTFT 随上下文长度线性抬升</td><td>RDMA 带宽、TTFT SLO</td></tr><tr><td>两池静态比例失配</td><td>一侧空闲、一侧队列堆积</td><td>GPU 秒浪费、Goodput 下降</td></tr><tr><td>层/页打包与 EP 分片不一致</td><td>decode 侧出现额外拷贝与同步</td><td>HBM 带宽、TPOT</td></tr></tbody></table>\n<p>因此这套方案适合高负载、长上下文、TTFT 与 TPOT 双 SLO 严格的集群部署；在低负载或短上下文场景，跨池传输与配比管理带来的复杂度换不回收益，混部反而更省。落地时的关键判断是：先测出本集群的 $B_{\\text{rdma}}$ 与典型 $S_{\\text{kv}}$ 分布，确认 $T_{\\text{kv}}$ 能被重叠窗口吸收，再决定是否物理分离；否则应先做 KV 压缩或缩短重叠窗口外的传输路径，而不是直接拆池。</p>\n<h3 id=\"alg-pd-disaggregation-moe-sec-15\">十五 · Goodput 目标函数与两阶段约束的耦合项</h3>\n<p>把预填解码分离部署写成一个可求解的问题，第一步是把目标写成可度量的形式。给定事实里的 Goodput 定义是单位 GPU 秒内满足 SLO 的请求数，约束是 TTFT 与 TPOT 各自不超过阈值。这个定义看似简单，但它把“快”与“稳”绑在同一个分母上：分母是总 GPU 秒，意味着任何一侧池子的空闲都会直接稀释 Goodput，而分子只统计同时满足两条 SLO 的请求，意味着任何一条超标都让该请求对目标零贡献。工程上必须把这两个约束展开成与并行策略相关的量，才能看出分离部署为什么必要。</p>\n<p>设一次请求的上下文长度为 $L$，输出长度为 $O$，prefill 池的 TP 度为 $t_p$、单卡算力为 $F$，decode 池的 EP 度为 $e_d$、单卡 HBM 带宽为 $B$。TTFT 可以拆成三段时间之和：prefill 计算时间、KV 跨池传输时间、decode 池首步调度与首 token 生成时间。关键的一步推导是把 prefill 计算时间写成与 TP 度成反比、同时叠加通信项的形式：</p>\n<div class=\"formula\">$$\\text{TTFT} \\approx \\underbrace{\\frac{c_{\\text{pf}}(L)}{t_p F}}_{\\text{prefill 计算}}+\\underbrace{\\frac{S_{\\text{KV}}(L)}{W_{\\text{RDMA}}}}_{\\text{KV 传输}}+\\underbrace{\\tau_{\\text{sched}}}_{\\text{首步开销}}$$</div>\n<p>其中 $c_{\\text{pf}}(L)$ 是单卡完成该上下文 prefill 所需的等效计算量，$S_{\\text{KV}}(L)$ 是 KV 字节数，$W_{\\text{RDMA}}$ 是跨池有效带宽。这一项是分离部署最容易被忽视的耦合：$t_p$ 增大能压低第一项，但 $S_{\\text{KV}}(L)$ 与 $L$ 成正比、与层数成正比，第二项不随 $t_p$ 缩小，于是 TTFT 的下界被传输项钳住。这就是为什么规模上限受 RDMA 带宽与 KV 传输量制约——上下文越长、层数越多，跨池传输越成为瓶颈。举例：长上下文在线服务里，若 $S_{\\text{KV}}(L)$ 在有效带宽下需要的时间已经接近 TTFT SLO 的相当比例，那么继续加大 $t_p$ 对 TTFT 的边际收益迅速衰减，此时正确的动作是把 KV 传输与 decode 计算流水重叠，而不是继续堆 TP。</p>\n<p>TPOT 一侧的推导方向相反。decode 每步要为整个 batch 的每个请求读一遍专家权重与 KV，属于带宽密集，单步时间近似为</p>\n<div class=\"formula\">$$\\text{TPOT} \\approx \\frac{\\sum_{i\\in \\text{batch}} S_{\\text{KV},i}+S_{W}}{e_d B}+\\tau_{\\text{comm}}$$</div>\n<p>这里 $S_W$ 是该步激活专家权重字节数，$e_d$ 把权重与 KV 的读取分摊到更多卡上，$\\tau_{\\text{comm}}$ 是 EP 的 all-to-all 代价。分母是 $e_d B$ 而非 $B$，说明 decode 池的 TPOT 由 EP 度与带宽共同决定；分子里 batch 求和说明 batch 越大单步越贵，但摊到每个 token 上反而更省，这正是 decode 池要“大而稳定 batch”的数学理由。两项合起来看：混部时同一个并行度既要服务 prefill 的算力需求又要服务 decode 的带宽需求，$t_p$ 与 $e_d$ 被迫取折中值，两个公式的右端同时变差，TTFT 与 TPOT 无法同时达标。分离部署的本质就是把这两个公式解耦，让 $t_p$ 只对 TTFT 负责、$e_d$ 只对 TPOT 负责。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-16\">十六 · 两池配比的吞吐方程与失配代价</h3>\n<p>分离之后紧接着的问题是配比。给定事实给出估算式 $N_p/N_d \\approx R_{\\text{prefill}}/R_{\\text{decode}}$，其中 $R$ 是两阶段单位时间请求处理能力。这个式子的推导关键一步是“稳态流量守恒”：在稳定负载下，prefill 池产出 KV 的速率必须等于 decode 池消费 KV 的速率，否则队列在一侧无界增长。设到达率为 $\\lambda$，prefill 池单 GPU 每秒能完成的请求数为 $r_p$，decode 池单 GPU 每秒能完成的请求数为 $r_d$，则守恒要求 $N_p r_p = N_d r_d = \\lambda$，两边相除即得上述配比式。它不是经验法则，而是排队系统在利用率接近饱和时的必要条件。</p>\n<p>把 $r_p$ 与 $r_d$ 展开，可以看到配比对负载配方极其敏感。$r_p$ 主要由 $t_p F / c_{\\text{pf}}(L)$ 决定，随上下文长度 $L$ 增大而下降；$r_d$ 主要由 $e_d B / (\\bar{O}\\cdot \\text{每 token 读取量})$ 决定，随输出长度 $\\bar{O}$ 增大而下降。于是同一集群在“长上下文短输出”和“短上下文长输出”两种流量下，最优 $N_p/N_d$ 完全不同。这就是静态配比的根本风险：比例按流量预测配置，突发流量下必然出现一侧空闲一侧过载。定量地看失配代价：若实际到达率是预测值的 $k$ 倍而配比不变，则瓶颈侧队列长度按 $(\\lambda-\\text{capacity})$ 线性累积，TTFT 或 TPOT 随队列等待时间单调恶化，同时另一侧 GPU 秒被浪费，Goodput 的分母被抬高、分子被压低，两个方向同时受损。</p>\n<p>工程上的处理不是消除失配，而是给失配留缓冲并让缓冲可观测。具体机制包括：按预测配比再乘一个安全系数预留冗余 GPU；在 prefill 池与 decode 池之间设置 KV 队列深度阈值，超过阈值即触发配比再平衡（迁移空闲池的实例或调整路由权重）；把 KV 传输与 decode 计算做成流水，使得传输延迟被计算掩盖而不是叠加在 TTFT 上。举例：突发流量到来时，prefill 池先饱和，KV 产出速率下降，decode 池因拿不到新 KV 而 batch 缩小、专家利用率下降，此时若无队列深度监控，运维只能看到端到端延迟上升而无法定位是哪一侧过载；有了分池队列指标，就能判断是该扩 prefill 还是扩 decode。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-17\">十七 · KV 打包格式与 EP 布局对齐的推导</h3>\n<p>KV 从 prefill 池传到 decode 池，格式必须与接收侧的专家分片布局一致，否则需要额外重排，增加显存拷贝与延迟。这一节的推导给出“按层/页打包”为什么是正确选择。设模型有 $n_l$ 层、每层 KV 头数为 $h$、头维为 $d$、每元素字节为 $b$，单请求单 token 的 KV 字节为 $2 n_l h d b$（K 与 V 各一份）。prefill 池按 TP 切分时，每张卡持有的是按头切分的局部 KV；decode 池按 EP 布局时，router 与专家在本地 rank，KV 需要按 decode 侧的注意力分片重新组织。若传输时按“整请求连续块”打包，接收侧必须做一次全量重排，拷贝量为整个 KV；若按层/页打包，则每一页可以独立寻址、独立写入目标页表，重排被消解为页级映射，拷贝量降为页内对齐开销。</p>\n<p>关键一步推导是把重排代价写成页大小的函数。设页大小为 $P$ 字节、页内对齐浪费为 $\\alpha P$，则总拷贝开销近似为 $S_{\\text{KV}}\\cdot\\alpha$ 加上页表更新开销 $n_{\\text{page}}\\cdot c_{\\text{meta}}$。当 $P$ 取到与 RDMA 传输粒度匹配时，$\\alpha$ 很小，页表更新可被批量提交摊薄；当 $P$ 过小，页表项数量爆炸，元数据开销主导；当 $P$ 过大，页内对齐浪费与部分页传输的带宽浪费上升。这就是“按层/页打包”的定量理由，也是失败模式“打包格式与本地专家分片不一致需额外重排”的根源：格式不一致等价于强制一次全量重排，拷贝量回到 $S_{\\text{KV}}$ 量级，延迟与显存带宽同时被吃掉。</p>\n<p>系统代价在这里体现为显存带宽与延迟的叠加。重排是一次读加一次写，占用 decode 池的 HBM 带宽，而 decode 池本来就是带宽密集的，重排会直接推高 TPOT。举例：decode 池正在连续批处理生成 token，若某批新到的 KV 需要重排，重排的读写会与当前步的权重读取争抢带宽，表现为该步 TPOT 出现尖峰。规避手段是在 prefill 侧就按 decode 侧的页表布局生成 KV，使接收侧只需页表挂接而无需数据搬移；这要求两池共享同一套页大小与分片约定，属于部署时必须对齐的接口契约，而不是运行时可临时协商的参数。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-18\">十八 · 流水重叠的伪代码与可实现性</h3>\n<p>把上述机制落到可实现层面，核心是一个双池异步流水：prefill 池完成一层或一页就发起 RDMA 写，decode 池在收到足够页后即可开始首步，而不是等整个请求的 KV 全部到齐。伪代码思路如下（用文字描述控制流，不写代码块）：prefill 侧对请求按层循环，每层计算完 K/V 后调用页打包函数生成页描述符（请求 id、层号、页号、目标地址），把描述符与数据一起提交给 RDMA 写队列，写完成事件回调里递减该请求的“待传页计数”；decode 侧维护一个按请求 id 索引的接收表，每收到一页就更新页表并递增“已到页计数”，当已到页计数达到首步阈值（足以计算首 token 所需的最小页集合）时，把该请求插入连续批处理队列，后续页到达时原地追加，不打断已开始的 decode 步。</p>\n<p>这个伪代码里有三个必须实现的细节。第一，页描述符要与 decode 侧的页表项一一对应，避免接收侧再做地址换算；第二，写完成事件必须与 decode 步的调度器解耦，用独立的事件队列消费，否则 RDMA 完成中断会打乱 decode 步的节奏；第三，首步阈值要按 SLO 推导而不是拍脑袋：设首步所需页数为 $m$，单页传输时间为 $P/W_{\\text{RDMA}}$，则首步等待时间约为 $mP/W_{\\text{RDMA}}$，把它控制在 TTFT SLO 减去 prefill 计算时间与首步开销之后的余量内，就得到 $m$ 的上界。这就是“KV 传输与 decode 计算流水重叠”的定量落地方式。</p>\n<p>系统代价方面，流水重叠并不消除 RDMA 带宽占用，只是把传输时间藏进计算时间。若传输时间大于 decode 单步时间，重叠失效，TTFT 仍被传输主导；若传输时间远小于单步时间，重叠收益饱和，此时继续优化传输对 TTFT 无贡献。举例：长上下文请求的 KV 传输时间若超过 decode 池单步时间，则首 token 必须等传输完成，流水只能掩盖后续页的传输而不能掩盖首步所需的页；这正是失败模式“长上下文时 RDMA 传输时间不可忽略导致 TTFT 超标”的机制解释。可实现的缓解是把首步阈值取得更小（只传注意力首步真正需要的页），让首 token 尽早发出，剩余页在后续 decode 步中陆续到达。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-19\">十九 · 量化方案独立选择对公式系数的影响</h3>\n<p>给定事实指出两池量化方案可独立选择（材料未给出具体位宽）。这一条在公式里体现为系数 $b$ 与 $S_W$ 的变化，值得单独推导，因为它改变的是配比方程里的 $r_p$ 与 $r_d$。KV 元素字节 $b$ 下降，则 $S_{\\text{KV}}(L)=2n_l hdb$ 同比下降，TTFT 公式里的传输项与 TPOT 公式里的 KV 读取项同时变小；权重字节 $S_W$ 下降，则 decode 单步的权重读取时间下降，$r_d$ 上升。于是量化让两个公式的右端同时改善，但它对两池的影响不对称：prefill 池是计算密集，量化主要降低传输项与显存占用，对计算时间 $c_{\\text{pf}}(L)/t_pF$ 的改善取决于是否使用低精度 MMA；decode 池是带宽密集，量化直接按比例降低带宽项，收益更直接。</p>\n<p>推导的关键一步是把量化位宽写进配比式。设 KV 位宽为 $b_{\\text{kv}}$、权重位宽为 $b_w$，则 $r_d \\propto e_d B/(\\bar{O}\\cdot(\\text{每 token KV 读取}+\\text{每 token 权重读取}))$，分子不变、分母随位宽线性下降，故 $r_d$ 随位宽下降而上升；$r_p$ 的分母里传输项随 $b_{\\text{kv}}$ 下降，故 $r_p$ 也上升但幅度受计算项钳制。两边都上升时，配比 $N_p/N_d$ 的变化方向取决于谁上升得更快：若 decode 侧因权重与 KV 双重降位宽而 $r_d$ 提升更多，则所需 decode GPU 数相对减少，配比应向 prefill 侧倾斜。这意味着量化方案的选择不是纯精度问题，它会移动两池的平衡点，部署时必须把量化配置纳入配比估算，而不是先定配比再选量化。</p>\n<p>系统代价是精度与稳定性的权衡。低精度 KV 会改变注意力输出的数值分布，长上下文下误差累积更明显；两池独立选择位宽意味着 prefill 写出的 KV 与 decode 读取的 KV 必须位宽一致，否则传输前要做一次转换，这又回到重排代价。举例：若 prefill 池用较高精度写 KV 而 decode 池按较低精度读，则每页到达后需要一次逐元素转换，转换占用 decode 池 HBM 带宽并推高 TPOT，收益被抵消。可实现的判断是：两池位宽必须在接口契约里锁定一致，量化收益才能体现在配比方程的系数上而不被转换开销吃掉。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-20\">二十 · 从公式到工程判断：何时分离、何时不分离</h3>\n<p>把前面几节的公式合起来，可以得到一个可操作的判断准则。分离部署的净收益等于“两阶段各自最优并行带来的 Goodput 提升”减去“KV 跨池传输的带宽开销与配比管理复杂度”。用公式表达，设混部时 TTFT 与 TPOT 中至少一项超 SLO 导致分子为零或很小，分离后两项均达标使分子恢复到接近到达率，则收益主要来自分子；代价项是传输时间 $S_{\\text{KV}}(L)/W_{\\text{RDMA}}$ 与失配缓冲占用的 GPU 秒。判断的关键是看传输项占 TTFT SLO 的比例：若该比例很小，分离几乎无代价；若该比例接近 SLO 余量，分离的收益被传输吃掉，此时应优先做流水重叠或降低 KV 位宽，而不是加大分离规模。</p>\n<p>另一个判断维度是负载是否足够高。低负载下两池都不会饱和，混部的资源争抢不显著，分离反而引入固定的传输开销与配比管理成本，Goodput 的分母因两池各自的低利用率而变大。高负载、长上下文、TTFT 与 TPOT 双 SLO 严格的集群部署才是分离的适用区间，这与给定事实的适用边界一致。举例：一个请求形态为长上下文在线服务的集群，prefill 池按 TTFT SLO 配置 TP 度、decode 池按 TPOT SLO 配置 EP 度与大 batch，若流量预测准确且留有缓冲，两池各自跑在高利用率区间，Goodput 提升来自 decode 池大而稳定的 batch 带来的专家利用率；若流量突发导致配比失配，则收益迅速转为亏损，说明分离部署的稳定性依赖配比管理而非并行策略本身。</p>\n<p>最后落到一个具体机制上：配比再平衡的触发条件应当由公式给出而不是由运维直觉给出。以队列深度为观测量，当 prefill 侧 KV 产出队列深度超过阈值 $Q_p$ 且 decode 侧 batch 未满时，说明 prefill 是瓶颈，应扩 prefill 或把 decode 空闲实例转为 prefill；反之亦然。阈值 $Q_p$ 可由 TTFT SLO 与单请求 KV 传输时间反推：队列等待时间上限等于 SLO 余量，除以单请求服务时间即得可容忍的队列长度。这样配比管理就从静态预测变成带反馈的闭环，突发流量下的失配被限制在缓冲范围内，而不是演化为一侧空闲一侧过载的整体恶化。</p>\n<h3 id=\"alg-pd-disaggregation-moe-sec-21\">二十一 · 请求形态的筛选：什么样的负载才配得上分离</h3>\n<p>分离部署不是普适加速器，它是一台对输入形状敏感的机器。把 prefill 池与 decode 池物理拆开之后，两池各自的最优并行策略（prefill 大 TP、decode 大 EP）才有意义；而一旦请求形态偏离配方，这套结构反而比混部更贵。判断一个负载是否“配得上”分离，看三个维度：上下文长度、输出长度、到达并发。</p>\n<p>长上下文在线服务是这套结构的天然客户。prefill 阶段的计算量随上下文长度近似线性增长，decode 阶段的每步开销则主要由权重带宽与 KV 读取决定，两者对 GPU 的需求曲线完全不同。当上下文足够长时，prefill 在混部中会长时间霸占 SM，把同批 decode 请求的 TPOT 顶穿；拆开之后，prefill 池按 TTFT SLO 配置 TP 度打满算力，decode 池按 TPOT SLO 配置 EP 度承载大 batch，两条 SLO 才能同时达标。反过来，短上下文、短输出的请求（比如分类、抽取、短问答）prefill 占比极低，拆池带来的 KV 跨池 RDMA 传输开销会直接吃掉收益——这类负载留在混部或分块预填捎带路径上更划算。</p>\n<p>输出长度决定 decode 池的驻留时间，也就决定了 decode 池需要多大的并发容量。一个输出 8 个 token 的请求和一个输出 2000 个 token 的请求，在 decode 池占用的 GPU 秒相差两个数量级；如果流量里长输出请求占比高，decode 池的 batch 会持续被占满，EP 专家利用率高，分离的收益被放大。反之，输出极短的流量会让 decode 池频繁换入换出 KV 页，连续批处理的批大小抖动，专家利用率反而下降。</p>\n<p>并发维度上，分离部署适合高负载集群：只有当两池都接近饱和时，静态配比才是有效率的；低负载下两池各自留有空闲，等于用两份 GPU 换一份吞吐。这里可以用一个粗粒度的判据：设流量到达率为 $\\lambda$，单请求平均占用 prefill 池的 GPU 秒为 $s_p$、占用 decode 池为 $s_d$，则两池的稳态占用分别为 $\\lambda s_p$ 与 $\\lambda s_d$。若 $\\lambda s_p$ 或 $\\lambda s_d$ 远小于池容量，分离的固定开销（KV 传输、两套调度器、两套显存管理）就摊不平。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-22\">二十二 · 长度分布与批大小的耦合：decode 池的 batch 是被输入喂出来的</h3>\n<p>decode 池的批大小不是调度器能自由设定的参数，它由长度分布与到达过程共同决定。连续批处理下，一个 decode 批由若干条正在生成的序列组成，每条序列每步读一次 KV 与专家权重。MoE 的专家并行让这件事更微妙：批内 token 经 router 分派到不同专家，只有当批足够大、token 在专家上的分布足够均匀时，每个 rank 上的专家 GEMM 才有足够多的行来摊薄权重读取的带宽成本。批太小，专家 GEMM 退化为窄矩阵乘，decode 池的带宽效率塌陷。</p>\n<p>长度分布对批大小的影响通过“驻留时间方差”传导。若请求输出长度高度同质（比如固定模板生成），decode 批内的序列几乎同时结束，批的换入换出整齐，批大小稳定在高位；若输出长度重尾分布，少数长序列长期占据批槽位，新请求只能填补短序列退出留下的空隙，批大小在高低之间反复摆动，专家利用率随之波动。工程上的应对是把长度分布作为配比输入：按输出长度的分位数估算 decode 池的平均驻留序列数，而不是按均值。</p>\n<p>KV 传输量与长度分布直接挂钩。KV 按层/页打包经 RDMA 从 prefill 池写入 decode 池，传输字节数正比于上下文长度乘以层数乘以每 token 每层的 KV 字节数。设上下文长度为 $L$、层数为 $n_l$、每层每 token 的 KV 字节数为 $b_{kv}$，则单请求 KV 传输量为 $L \\cdot n_l \\cdot b_{kv}$。这个量在长上下文下不可忽略：当传输时间与 decode 首步计算不能充分重叠时，TTFT 被 RDMA 传输主导，prefill 池算得再快也没用。因此长度分布的上尾（最长的那批上下文）才是配比与流水设计的真正约束，均值会骗人。</p>\n<div class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$</div>\n<p>这个式子说明分离部署的目标不是单请求最快，而是单位 GPU 秒内满足双 SLO 的请求数最多。长度分布决定了哪些请求能落进 SLO 窗口：长上下文请求的 TTFT 被 prefill 计算与 KV 传输两段串联约束，短输出请求的 TPOT 约束则相对宽松。配比与批大小的调优，本质上是在这个比值上做梯度上升，而不是分别优化两池的局部吞吐。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-23\">二十三 · 并发与配比：静态比例在什么流量下成立</h3>\n<p>两池 GPU 数的配比按吞吐方程估算：$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$，其中 $N_p$、$N_d$ 为两池 GPU 数，$R_{\\text{prefill}}$、$R_{\\text{decode}}$ 为两阶段单位时间请求处理能力。这个方程的成立前提是流量平稳：$R_{\\text{prefill}}$ 与 $R_{\\text{decode}}$ 都是按目标负载的长度分布与批大小测出来的常数，一旦流量形状变化，这两个常数就漂移，配比随之失准。</p>\n<p>具体例子：一个以长上下文问答为主的集群，按预测把 60% 的 GPU 给 prefill 池、40% 给 decode 池。某时段流量突变为大量短上下文、长输出的生成请求，prefill 计算量骤降，prefill 池大量空闲，而 decode 池因输出变长、驻留序列增多而迅速过载，TPOT 超标。此时整体吞吐与 SLO 同时恶化：空闲的 prefill GPU 无法被 decode 池借用，因为两池的并行策略与显存布局不同，KV 存储格式也不同。这就是静态配比的结构性代价——它把弹性从系统里拿走了。</p>\n<p>并发上升时还有第二重效应：prefill 池的批由到达请求组成，批越大，单次 prefill 的算力效率越高，但排队时延也越长。TTFT SLO 约束的是“排队 + prefill 计算 + KV 传输”三段之和，高并发下排队段膨胀，prefill 池即便算力充足也会 TTFT 超标。这意味着配比不能只按算力平衡，还要按 SLO 反推可接受的排队深度，进而反推 prefill 池的并发上限。decode 池同理：TPOT SLO 约束每步间隔，批越大单步越慢，存在一个使 TPOT 恰好达标的批大小上限，超过它就得加 GPU 而不是加批。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-24\">二十四 · 负载不对时的三种失败形态</h3>\n<p>第一种是比例失配。突发流量下 prefill 池或 decode 池单侧过载，另一侧 GPU 空闲，整体吞吐与 SLO 同时恶化。这种失败的特征是两池利用率曲线背离：一侧排队长度飙升，另一侧 SM 利用率掉到低位。它不会自我纠正，因为配比是静态配置的，调度器没有跨池借调的通道。工程上的缓解是按流量预测留缓冲，把配比向更容易突发的一侧倾斜，代价是常态下另一侧的低利用率。</p>\n<p>第二种是传输主导。长上下文请求的 KV 跨池 RDMA 传输时间不可忽略，若与 decode 计算未充分重叠，TTFT 被传输段主导。设 KV 传输时间为 $t_{kv}$、prefill 计算时间为 $t_p$、decode 首步时间为 $t_{d1}$，则 TTFT 近似为 $t_p + \\max(t_{kv}, t_{d1})$（流水重叠理想时）或 $t_p + t_{kv} + t_{d1}$（无重叠时）。两种情况的差距就是流水设计的价值所在。上下文越长、层数越多，$t_{kv}$ 越大，无重叠的代价越不可接受；而当 RDMA 带宽被多请求并发传输挤占时，单请求的 $t_{kv}$ 还会进一步拉长，形成正反馈式的 TTFT 恶化。</p>\n<p>第三种是格式重排。decode 池按 EP 布局接收 KV 时，若层/页打包格式与本地专家分片不一致，需要额外重排，增加显存拷贝与延迟。这不是带宽问题而是布局问题：KV 在 prefill 池按 TP 切分生成，每个 rank 持有部分注意力头的 KV；decode 池按 EP 布局，注意力头的分布与专家分片的对应关系不同，接收端必须把 KV 重新映射到本地布局。重排发生在 decode 池的接收路径上，直接叠加到 TTFT 上，且随层数线性累积。避免它的办法是在打包阶段就按 decode 池的目标布局写 KV，让 prefill 池承担布局转换的计算，把重排从关键路径上挪走。</p>\n<table class=\"mini\"><thead><tr><th>失败形态</th><th>触发条件</th><th>可观测信号</th><th>主要代价</th></tr></thead><tbody><tr><td>比例失配</td><td>流量形状突变、突发到达</td><td>两池利用率背离、单侧排队飙升</td><td>吞吐与 SLO 同时恶化，空闲 GPU 无法借用</td></tr><tr><td>传输主导</td><td>长上下文、RDMA 带宽被挤占</td><td>TTFT 随上下文长度超线性增长</td><td>TTFT 超标，prefill 算力被传输段浪费</td></tr><tr><td>格式重排</td><td>打包布局与 EP 分片不一致</td><td>decode 接收路径延迟随层数累积</td><td>额外显存拷贝，TTFT 叠加</td></tr></tbody></table>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-25\">二十五 · 把负载配方写进部署参数</h3>\n<p>负载配方最终要落到可执行的部署参数上：prefill 池的 TP 度、decode 池的 EP 度与批大小上限、两池 GPU 数配比、KV 传输的流水深度、以及缓冲比例。这些参数不是独立调出来的，它们被同一组 SLO 与同一份长度分布耦合在一起。一个可操作的顺序是：先按 TTFT SLO 与长度分布的上尾定 prefill 池的 TP 度与并发上限，再按 TPOT SLO 定 decode 池的批大小上限与 EP 度，然后用吞吐方程算初始配比，最后按流量预测的方差留缓冲并把 KV 传输与 decode 计算做成流水。</p>\n<p>配方里最容易被忽略的是“拒绝的形状”。分离部署在负载不对时不会优雅降级，它会同时违反两条 SLO。因此部署侧需要一个准入判断：当请求的上下文长度超过某个阈值、且当前 RDMA 带宽余量不足以在 TTFT 窗口内完成传输时，这类请求应被路由到混部路径或分块预填捎带路径，而不是硬塞进分离结构。这个阈值由 $t_{kv}$ 与 SLO 窗口的关系决定，随集群负载动态变化，不能写死。</p>\n<p>另一个工程判断是缓冲的放置位置。缓冲加在 prefill 池一侧，吸收的是突发到达造成的排队；加在 decode 池一侧，吸收的是输出长度方差造成的驻留波动。两者性质不同，不能用一个统一的余量系数糊过去。按流量预测静态配置两池比例并留缓冲，是这套结构在缺少跨池弹性时的唯一稳定手段；缓冲给错侧，等于把过载从一处搬到另一处。</p>\n<p>最后落在具体机制上：KV 传输与 decode 计算流水重叠的设计，决定了长上下文负载下分离部署是否还能守住 TTFT。把 KV 按层/页打包、逐层传输、decode 池逐层接收并立即开始该层的注意力计算，可以让 $t_{kv}$ 与 $t_{d1}$ 在层粒度上交错，把串联的 $t_p + t_{kv} + t_{d1}$ 压到接近 $t_p + \\max(t_{kv}, t_{d1})$。层数越多，这种层粒度流水的收益越大，而它成立的前提正是负载配方里那条“长上下文、层数多”的形态判断——配方错了，流水设计得再好也只是在错误的负载上做正确的无用功。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-26\">二十六 · 负载配方：长上下文在线服务是它的主场，错配流量是它的死穴</h3>\n<p>分离部署不是普适加速器，它有一个明确的负载配方：请求形态是长上下文在线服务，prefill 与 decode 都有严格 SLO，且集群负载足够高到让两个池都不闲着。prefill 池按 TTFT SLO 配置 TP 度，用大 TP 把算力打满；decode 池按 TPOT SLO 配置 EP 度，用大 batch 提升专家利用率。两池比例按吞吐方程估算 <span class=\"formula\">$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</span>，其中 $N_p$、$N_d$ 为两池 GPU 数，$R_{\\text{prefill}}$、$R_{\\text{decode}}$ 为两阶段单位时间请求处理能力。这个比例是静态配置的，它的前提是流量可预测。反过来，短 prompt、低并发、TTFT 宽松而 TPOT 敏感的负载，拆池只会引入无谓的 RDMA 开销和管理复杂度，收益被传输成本吃掉。</p>\n<p>负载不对时的第一类失效是比例失配。突发流量到来，prefill 池先被打满，decode 池空转等 KV；或者 decode 池 batch 已满、prefill 池排队，TTFT 直接超标。此时整体 Goodput <span class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$</span> 同时被两侧拖垮——一侧过载、一侧空闲，GPU 秒被浪费在等待而非计算上。静态配比留缓冲只能缓解，不能消除突发下的单侧过载。</p>\n<p>第二类失效来自长上下文本身。上下文越长、层数越多，KV 跨池传输量越大，RDMA 带宽成为规模上限。KV 按层/页打包经 RDMA 写入 decode 池，若传输与 decode 计算未充分流水重叠，TTFT 就被传输时间主导而非 prefill 计算主导。第三类失效在格式对齐：decode 池按 EP 布局接收 KV 时，若层/页打包格式与本地专家分片不一致，需要额外重排，增加显存拷贝与延迟，等于把省下的争抢代价又还了回去。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>适配判断</th><th>主要代价</th></tr></thead><tbody><tr><td>长上下文、双 SLO 严格、高负载</td><td>适配，两池各自最优并行</td><td>RDMA 传输与静态配比管理</td></tr><tr><td>短 prompt、低并发</td><td>不适配，拆池收益被传输吃掉</td><td>跨池 KV 开销、池间空转</td></tr><tr><td>突发流量、比例失配</td><td>失效，单侧过载</td><td>吞吐与 SLO 同时恶化</td></tr><tr><td>超长上下文、格式不一致</td><td>受 RDMA 带宽与重排制约</td><td>TTFT 被传输主导、显存拷贝</td></tr></tbody></table>\n<h3 id=\"alg-pd-disaggregation-moe-sec-27\">二十七 · 硬件档位与两池的物理边界</h3>\n<p>部署配方第一步不是选框架，而是把硬件切成两个物理上可独立调度的故障域。prefill 池与 decode 池之间只保留 RDMA 通路，不共享 HBM、不共享 NVLink 域内的 SM 资源。工程上按档位划分：prefill 池优先吃满单卡算力密度与 NVLink 5 域内带宽，因为它的瓶颈是 MMA 吞吐与注意力计算的平方项；decode 池优先吃满 HBM 容量与跨节点 EP 通信带宽，因为它的瓶颈是每 token 的权重读取与专家 All-to-All。GB200 NVL72 这类机柜级域适合做 decode 池的 EP 分组——72 个 GPU 在同一 NVLink 域内，专家分片可以跨 rank 放置而 All-to-All 不落 RDMA；prefill 池则可以用更小的 TP 组，把 NVLink 域留给张量并行的 All-Reduce。</p>\n<p>档位选择的判据是带宽账，不是算力账。设单请求上下文长度为 $L$、层数 $l$、每层 KV 字节数为 $b$，则跨池传输量为 $L \\cdot l \\cdot b$。prefill 池的算力决定这段 KV 多快被生产出来，decode 池的 RDMA 入带宽决定它多快被消费，两者必须匹配：</p>\n<div class=\"formula\">$$T_{\\text{xfer}} = \\frac{L \\cdot l \\cdot b}{B_{\\text{rdma}}}, \\quad T_{\\text{xfer}} \\le \\text{SLO}_{\\text{TTFT}} - T_{\\text{prefill}}$$</div>\n<p>这个不等式是档位选择的硬约束。若 $T_{\\text{prefill}}$ 已经被压到很小而 $T_{\\text{xfer}}$ 占了大头，说明 prefill 池的算力档位过剩、RDMA 档位不足，应把预算挪到网卡与交换侧，而不是继续堆 GPU。具体例子：长上下文在线服务里，prefill 池用 8 卡大 TP 把单请求预填压到数百毫秒量级，此时若 KV 打包后单请求传输量达到数十 MB 级，则必须保证每请求分摊到的 RDMA 带宽足以在剩余 TTFT 预算内完成传输，否则 TTFT 由传输主导——这正是失败模式里“长上下文 RDMA 传输时间不可忽略”的物理来源。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-28\">二十八 · 并行拓扑：prefill 用 TP、decode 用 EP 的不可交换性</h3>\n<p>两池的并行拓扑不能互换，原因是两种阶段的通信模式完全不同。prefill 阶段每个 token 都要过全部专家（在稠密等效意义下），计算是规则的 GEMM 堆叠，TP 把权重切到多卡后每卡只算一部分、再用 All-Reduce 合并部分和，通信量与激活大小成正比、与 batch 弱相关，因此大 TP 能把单请求延迟压下来。decode 阶段每 token 只激活少数专家，计算是稀疏的、访存主导的，TP 切分会让每卡都读一遍完整激活却只算一小块权重，收益递减；EP 则把专家分散到不同 rank，每卡只驻留自己那份专家权重，batch 越大专家命中越均匀、利用率越高。</p>\n<p>拓扑参数要写成显式配置而非默认值。prefill 池：TP 度按 TTFT SLO 反解，TP 越大单请求预填越快但每 GPU 的有效吞吐下降，存在一个使 goodput 最大的拐点；EP 在 prefill 池内通常设为 1 或与 TP 正交的小值，因为预填阶段专家负载已被大 batch 摊平。decode 池：EP 度按 TPOT SLO 与显存容量联合确定，EP 越大单卡专家权重越少、HBM 压力越小，但 All-to-All 跳数增加。伪代码式的配置思路：</p>\n<ul>\n<li>输入：$\\text{SLO}_{\\text{TTFT}}$、$\\text{SLO}_{\\text{TPOT}}$、上下文长度分布、到达率 $\\lambda$</li>\n<li>prefill：枚举 TP ∈ {2,4,8}，测单请求 $T_{\\text{prefill}}(L)$，取满足 $T_{\\text{prefill}} + T_{\\text{xfer}} \\le \\text{SLO}_{\\text{TTFT}}$ 的最小 TP</li>\n<li>decode：枚举 EP ∈ {8,16,32,64}，测每 token 的 $T_{\\text{decode}}$ 与专家利用率，取满足 $\\text{TPOT} \\le \\text{SLO}_{\\text{TPOT}}$ 且 HBM 不溢出的最大 EP</li>\n<li>校验：用吞吐方程算 $N_p/N_d$，若与硬件档位冲突则回退重选</li>\n</ul>\n<p>代价体现在通信域上：decode 池 EP 度一旦跨出 NVLink 域，All-to-All 就落到 RDMA，与 KV 跨池传输争抢同一张网卡，TPOT 抖动随之上升。因此 decode 池的 EP 分组应尽量落在单个 NVL72 域内，把 RDMA 带宽留给 KV 传输。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-29\">二十九 · 量化方案：两池独立选择及其对传输量的连带影响</h3>\n<p>量化方案在两池可以独立选择，这是分离部署相对混部的一个实打实的自由度。prefill 池的计算瓶颈在 MMA，权重与激活都走低精度能直接提升算力利用率，且预填阶段数值误差对最终质量的影响被后续 decode 稀释；decode 池的瓶颈在权重读取带宽，权重量化直接决定每 token 的 HBM 读取量，激活量化的收益则小得多。因此常见组合是 prefill 池权重与激活同时低精度、decode 池权重低精度而激活保持较高精度。</p>\n<p>关键连带效应在 KV 上：KV 的数值格式决定跨池传输量 $b$。若 prefill 池以低精度写 KV、decode 池以同格式读，则 $T_{\\text{xfer}}$ 按比例缩小；若两池 KV 格式不一致，decode 池接收后需做一次反量化或重排，这正是失败模式里“层/页打包格式与本地专家分片不一致需额外重排”的来源。工程判断：KV 格式应在两池间统一，量化自由度只留给权重与激活，不要留给 KV——统一格式省下的重排显存拷贝与延迟，通常比 KV 再压一档带来的带宽收益更值。</p>\n<p>量化对显存的连带影响也要算进 decode 池的 EP 度选择：权重低精度后单卡可驻留的专家数上升，EP 度可以调小、All-to-All 跳数下降，TPOT 改善；但 KV 若未同步压缩，长上下文下 KV 仍会挤占专家权重空间——这部分与分页 KV 和专家权重共存的显存预算直接相关，此处只作指路，不展开。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-30\">三十 · KV 策略：打包粒度、流水重叠与释放时机</h3>\n<p>KV 策略的核心是把“传输”从“计算”的关键路径上摘下来。打包粒度按层/页组织：按层打包使 decode 池可以在收到第 $k$ 层 KV 后立即开始第 $k$ 层的 decode 计算，不必等全部层到齐，形成层级的流水重叠；按页打包则与 decode 池的分页 KV 分配器对齐，减少接收侧的碎片与重排。两者可组合：以页为分配单位、以层为传输单位。</p>\n<p>流水重叠的收益可以用重叠率刻画：设总传输时间 $T_{\\text{xfer}}$、decode 首 token 计算时间 $T_{\\text{first}}$，则有效首 token 等待为</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} \\approx T_{\\text{prefill}} + \\max\\left(T_{\\text{xfer}} - T_{\\text{first}},\\ 0\\right) + T_{\\text{first}}$$</div>\n<p>当 $T_{\\text{first}} \\ge T_{\\text{xfer}}$ 时传输被完全隐藏，TTFT 退化为 $T_{\\text{prefill}} + T_{\\text{first}}$；反之传输暴露。这解释了为什么 decode 池的 EP 度不能一味调大：EP 越大首层计算越慢，$T_{\\text{first}}$ 越长，反而更容易隐藏传输——这是一个正向耦合，但代价是 TPOT 变差，需要在两个 SLO 之间取平衡。</p>\n<p>释放时机同样影响容量：KV 在 decode 池原地追加，请求完成后立即释放并归还分页池，避免长尾请求占住显存拖累后续 batch 的专家驻留。具体例子：一个长上下文请求在 decode 池生成数百 token 后结束，若释放延迟一个调度周期，分页池的空闲页就被占住，下一批请求的连续批处理被迫缩小 batch，专家利用率下降、TPOT 抬升——释放延迟的代价不在单请求，而在整池的批处理规模。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-31\">三十一 · 调度参数与两池配比的可复现配置思路</h3>\n<p>两池配比按吞吐方程估算，但方程里的 $R_{\\text{prefill}}$、$R_{\\text{decode}}$ 必须用实测而非理论峰值：</p>\n<div class=\"formula\">$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}},\\quad \\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}}$$</div>\n<p>可复现的配置流程分四步。第一步，固定上下文长度分布与到达率，在单池上分别测出 prefill 池的每 GPU 请求处理能力与 decode 池的每 GPU token 产出能力，换算成同一时间窗内的请求处理能力。第二步，按上式定初始配比，再按预测流量的峰值留缓冲——缓冲的方向要偏 decode 池，因为 decode 池的 batch 大而稳定，多出的 GPU 能直接转化为专家利用率，而 prefill 池多出的 GPU 在低峰期只能空转。第三步，设调度参数：prefill 池按 TTFT SLO 设最大批 token 数与分块大小，decode 池按 TPOT SLO 设连续批处理的最大并发序列数与每步 token 预算；两池的队列深度要解耦，prefill 池的排队不应传导到 decode 池的批处理节奏。第四步，把 KV 传输与 decode 计算做成流水，用层级打包保证首层先到。</p>\n<p>稳定性技巧落在配比管理上：静态配比在突发流量下必然出现一侧空闲一侧过载，缓解手段不是动态改配比（改配比意味着重新划分物理域，代价是重配与冷启动），而是在两池各自留可吸收的队列缓冲，并让 prefill 池在过载时优先保 TTFT、decode 池在过载时优先保 TPOT——两个 SLO 各自守门，避免单侧过载把另一侧的指标一起拖垮。失败模式的观测点很明确：prefill 池队列长度持续上升而 decode 池 GPU 利用率下降，说明 $N_p/N_d$ 偏小；反向则偏大。这两个信号应作为配比调整的触发条件，而不是等 SLO 违约后再补救。</p>\n<p>最后落在工程判断上：这套配方的可复现性来自把每个参数都绑定到一个可测的量——TP 度绑 TTFT、EP 度绑 TPOT 与 HBM、KV 格式绑 $T_{\\text{xfer}}$、配比绑两池实测吞吐比。任何一个参数脱离它的绑定约束去调，都会在另一侧制造看不见的代价；分离部署的收益不是来自拆分本身，而是来自拆分后每个参数终于可以只对一个 SLO 负责。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-32\">三十二 · 比例失配与 RDMA 传输：这套配方的失效边界</h3>\n<p>这套部署配方的核心假设是两池负载可预测。配比按吞吐方程估算：$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}}$$ 其中 $R_{\\text{prefill}}$ 由 prefill 池的 TP 度与算力决定，$R_{\\text{decode}}$ 由 decode 池的 EP 度、batch 上限与 TPOT SLO 共同约束。问题在于 $R_{\\text{decode}}$ 不是常数：decode 池的连续批处理在 batch 未打满时，单位 GPU 秒产出的 token 数随并发线性上升，一旦 batch 触顶则饱和。于是同一组 $N_p/N_d$ 在低峰期表现为 decode 池空闲、prefill 池排队，在突发流量下则反转为 decode 池过载、prefill 池空转，两种失配同时恶化 TTFT 与 TPOT，Goodput 按 $$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$ 直接塌陷。工程上必须把比例当作带缓冲的静态配置：按峰值流量的 $R_{\\text{prefill}}/R_{\\text{decode}}$ 上浮一档留出 decode 侧余量，因为 decode 池过载表现为 TPOT 超标（用户可感知的逐 token 卡顿），而 prefill 池过载只抬高 TTFT，后者对短请求更敏感、对长上下文请求反而被 KV 传输时间掩盖。</p>\n<p>第二个失效条件是跨池 KV 传输。KV 按层/页打包后经 RDMA 写入 decode 池，传输量正比于层数、上下文长度与 KV 头维度，传输时间与 decode 池接收侧的写入带宽成反比。当上下文足够长时，单请求的 KV 传输时间可以超过该请求在 prefill 池的算力时间，此时 TTFT 由 RDMA 主导而非计算主导——加大 prefill 池 TP 度毫无收益，瓶颈转移到网络。缓解手段是让 KV 传输与 decode 计算流水重叠：prefill 池按层产出 KV 即开始传输，decode 池收到首层 KV 即可启动该请求的 decode 步，不必等全部层到齐；但这要求 decode 池的 EP 布局在接收侧按本地专家分片直接落位，若打包格式与本地 rank 的专家分片不一致，就要额外重排，增加显存拷贝与延迟，重叠收益被吃掉。因此打包格式必须在两池间统一约定，按 decode 池的 EP 切分顺序组织页表，而不是按 prefill 池的 TP 切分顺序。</p>\n<p>量化方案两池可独立选择，这正是分离部署的隐性收益：prefill 池计算密集，可选用更激进的低精度矩阵乘以打满算力；decode 池带宽密集，权重与 KV 的读取带宽才是主约束，量化位宽的选择要按 KV 传输量与显存占用权衡，而非单纯追求算力峰值。代价是两池精度路径不同，跨池传递的 KV 必须统一到 decode 池的数值格式，格式转换若发生在传输路径上会引入额外拷贝。下表给出配方的边界判断：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>配方表现</th><th>主导代价</th></tr></thead><tbody><tr><td>高负载、长上下文、双 SLO 严格</td><td>两池各自最优并行，TTFT 与 TPOT 同时达标</td><td>RDMA 带宽与静态配比管理</td></tr><tr><td>突发流量、比例失配</td><td>一侧过载一侧空闲，Goodput 下降</td><td>GPU 秒浪费</td></tr><tr><td>超长上下文、传输未重叠</td><td>TTFT 被 RDMA 传输主导</td><td>网络时延</td></tr><tr><td>打包格式与 EP 分片不一致</td><td>接收侧重排，显存拷贝增加</td><td>显存带宽与延迟</td></tr></tbody></table>\n<p>规模上限由此确定：上下文越长、层数越多，单请求 KV 传输量越大，decode 池接收带宽成为硬约束，此时增大集群规模只增加 prefill 算力而不增加传输带宽，边际收益递减。可复现的配置思路是先按目标上下文的 KV 传输量估算 decode 池接收带宽需求，再反推两池比例与 RDMA 链路数，最后用流水重叠把传输时间压到 TTFT SLO 的预算之内；若估算显示传输时间已占 TTFT 预算的主要部分，这套物理分离方案对该负载形态不再成立，应退回分块预填捎带或缩短上下文分片。</p>\n<h3 id=\"alg-pd-disaggregation-moe-sec-33\">三十三 · 显存账：两池各自的第一道墙</h3>\n<p>分离部署把显存压力从一张卡上拆成两份互不相同的账本。prefill 池的显存主要被激活值、临时 workspace 与大 TP 下的权重分片占据，KV 只是过路产物，写完即走；decode 池则相反，权重按 EP 切分后单卡占比下降，但连续批处理把 batch 拉大，KV cache 随 batch×上下文长度线性膨胀，成为真正的容量约束。设 decode 池单卡可用显存为 $M$，权重与运行时开销占 $M_w$，每 token 每层 KV 字节数为 $b_{kv}$，层数 $L$，则单卡可容纳的并发 token 总量近似为</p>\n<div class=\"formula\">$$T_{\\max}\\approx \\frac{M-M_w}{L\\cdot b_{kv}}$$</div>\n<p>这个式子的工程含义是：decode 池的 batch 上限不是由算力决定，而是由 $T_{\\max}$ 除以平均上下文长度决定。长上下文在线服务里，平均上下文从 4K 涨到 32K，同样的显存能承载的并发请求数掉到八分之一，EP 度再高也救不回来——专家利用率的分母是 batch，batch 被 KV 卡死，专家并行带来的吞吐收益就被显存上限截断。具体例子：decode 池按 EP 布局接收 KV 时，若层/页打包格式与本地专家分片不一致，需要额外重排，这笔重排既吃显存（要一块中转 buffer）又吃拷贝带宽，在长上下文下会直接压缩 $T_{\\max}$。因此分离部署的显存规划必须把 KV 当作一等公民：prefill 池按峰值激活值配，decode 池按 SLO 允许的最大并发 token 数配，两池的显存余量不能互相借用。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-34\">三十四 · 带宽账：RDMA 传输量与重叠窗口</h3>\n<p>跨池 KV 传输是这套架构新增的、混部方案里不存在的开销。传输量由请求的上下文长度、层数与每 token 每层 KV 字节数决定，单请求传输字节数为 $S=L\\cdot c\\cdot b_{kv}$，$c$ 为上下文 token 数。设 RDMA 有效带宽为 $B$，则纯传输时间为 $S/B$。关键在于这个时间是否被隐藏：prefill 池生成 KV 是按层推进的，第 $i$ 层算完即可打包发出，decode 池收到第 $i$ 层就能开始该层的 decode 计算，形成层间流水。理想情况下 TTFT 由首层传输加首层 decode 决定，而非整段 KV 传完；但流水要成立，需要两侧的层节奏匹配——prefill 池大 TP 下单层计算很快，若 RDMA 带宽不足以在同样时间内送走该层 KV，prefill 池就会被反压，算力空转。这就是规模上去后第一个崩点：**prefill 池的算力被 RDMA 带宽反压**。工程判断是算“层带宽需求”而非“请求带宽需求”：每层 KV 字节数除以单层计算时间，得到维持流水所需的最低带宽，低于这个值，加 GPU 只会让 prefill 池等得更久。长上下文使 $S$ 线性增长而单层计算时间基本不变，所以上下文越长，这个比值越先越界。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-35\">三十五 · 通信账：EP 布局接收与 all-to-all 的叠加</h3>\n<p>decode 池按 EP 承载大 batch，MoE 层每 token 要经过 router 与专家分发的 all-to-all。分离部署并没有消除这笔通信，只是把它从“与 prefill 争抢”变成“decode 池内部的稳定开销”。真正的新问题是两笔通信叠加：KV 从池外经 RDMA 进来，专家 all-to-all 在池内 NVLink 域内进行，二者共享 decode 池的网络入口与内存子系统。当 batch 大、上下文长时，KV 写入的持续流量会与 all-to-all 的突发流量在同一张网卡上排队，尾延迟由此产生。设 decode 池单 token 的专家通信量为 $V_{moe}$，KV 流入速率为 $R_{kv}$，网卡有效吞吐为 $C$，则稳定条件为 $R_{kv}+B\\cdot V_{moe}/t_{tok}\\le C$，其中 $t_{tok}$ 为 token 间隔。规模上去后，$R_{kv}$ 随并发请求数线性涨，而 $C$ 是固定的，先崩的是 decode 池的入口带宽，表现为 TPOT 的 P99 抬升而非均值恶化——均值被连续批处理摊平，尾部请求恰好撞上 KV 批量到达与 all-to-all 峰值重合。缓解手段是给 KV 流入设优先级与限速，让 all-to-all 有确定的窗口，代价是 KV 传输更慢、TTFT 变差，这是一个必须显式取舍的旋钮。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-36\">三十六 · 功耗与配比：静态比例在突发流量下的崩塌</h3>\n<p>两池资源配比按吞吐方程估算 $N_p/N_d\\approx R_{\\text{prefill}}/R_{\\text{decode}}$，这个比例是静态配置的，而流量是突发的。比例失配时，一侧 GPU 空闲、另一侧过载，整体吞吐与 SLO 同时恶化：prefill 池过载表现为 TTFT 超标（请求排队等算力），decode 池过载表现为 TPOT 超标（batch 被 KV 与带宽双重挤压）。功耗维度上，两池的功率特性不同——prefill 池大 TP 打满算力时接近功耗墙，decode 池带宽密集、算力利用率低但显存与网络活跃，功率密度较低。静态配比意味着功率预算也静态切分，prefill 池为峰值算力预留的功率在低峰期闲置，decode 池在突发时又无法借用。规模上去后，这个矛盾被放大：集群越大，流量预测的相对误差越小但绝对失配量越大，单侧过载的 GPU 数足以拖垮整体 goodput。可操作的做法是把配比做成两级——粗粒度按预测静态切分，细粒度允许 decode 池在 KV 流入受限时临时借用少量 prefill 卡做 piggyback 式解码，代价是并行策略折中，只在缓冲区间内启用。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-37\">三十七 · 尾延迟：三个先崩点的排序</h3>\n<p>把上述代价按“规模上去后谁先崩”排序，需要看各约束随规模的伸缩性。KV 传输量随上下文长度线性增长、与并发数线性叠加，是最先越界的量；decode 池入口带宽是固定资源，KV 流入与专家 all-to-all 叠加后尾延迟最先恶化；显存上限 $T_{\\max}$ 随上下文长度反比下降，决定 batch 天花板，属于第二道墙；两池静态配比在突发下失配，属于管理层面的崩塌，放大前两者的后果。用 goodput 约束表达：</p>\n<div class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$</div>\n<p>注意分母是总 GPU 秒，包含两池全部卡，因此任何一侧的空闲都直接稀释 goodput。具体例子：长上下文请求的 KV 跨池 RDMA 传输时间不可忽略、与 decode 计算未充分重叠时，TTFT 被传输主导，请求虽最终完成但不满足 SLO，计入分子为零却消耗了分母——这类请求是 goodput 的最大杀手，且随上下文变长占比上升。工程上应把“传输未重叠”当作独立的失败模式监控，而不是笼统看 TTFT 均值。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-38\">三十八 · 规模上限的工程判断</h3>\n<p>这套架构的规模上限由 RDMA 带宽与 KV 传输量共同决定，上下文越长、层数越多，跨池传输越成为瓶颈。判断一个集群是否还能继续加卡，看的不是总算力，而是三个比值：prefill 池层带宽需求与可用 RDMA 带宽之比、decode 池 KV 流入速率与网卡有效吞吐之比、$T_{\\max}$ 与 SLO 允许并发 token 数之比。任一比值逼近 1，加卡收益就被该项吞掉。可行的扩容顺序是先提 RDMA 带宽与重叠深度（层间流水、按页细粒度发送），再扩 decode 池显存以抬高 batch 天花板，最后才加 prefill 算力——因为 prefill 算力在带宽受限时是空转的。反过来，若三个比值都远离 1 而 goodput 仍上不去，问题在配比而非容量，应回到静态比例的缓冲区间调整，而不是继续堆硬件。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-39\">三十九 · 规模上去先崩在哪：RDMA 带宽、两池配比与尾延迟的三角约束</h3>\n<p>把 prefill 与 decode 拆成两个物理池之后，系统的第一个瓶颈并不是算力，而是<strong>跨池 KV 传输的字节量随上下文长度线性增长</strong>。KV 按层/页打包后经 RDMA 写入 decode 池，单请求传输量可写成 $B_{\\text{KV}} = L \\cdot H_{\\text{kv}} \\cdot S \\cdot b_{\\text{elem}}$（$L$ 层数、$H_{\\text{kv}}$ KV 头维度总量、$S$ 序列长度、$b_{\\text{elem}}$ 每元素字节数）。关键点是：prefill 池的算力随 $S$ 增长是超线性的（注意力项 $O(S^2)$），而传输时间随 $S$ 线性增长，两者在某个上下文长度处交叉——超过该点，TTFT 由 RDMA 传输主导而非计算主导。工程含义很直接：prefill 池再快也没用，因为首 token 要等 KV 落到 decode 池才能开始 decode。缓解手段是把传输与 decode 计算做流水重叠，即按层/页分块发送、decode 侧收到前若干层即启动，但这要求 decode 池的 EP 布局与打包格式严格对齐，否则触发额外重排与显存拷贝，重叠收益被吃掉。</p>\n<p>第二个崩点是两池配比。按吞吐方程估算 $\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$，其中 $R$ 是两阶段单位时间请求处理能力。这个比例是静态配置的，而真实流量在突发时请求形态会漂移：长上下文请求比例上升会同时抬高 $R_{\\text{prefill}}$ 的耗时和 KV 传输量，等效于把 prefill 池的相对能力压低，于是 prefill 侧排队、TTFT 超标，而 decode 池因拿不到 KV 而空闲——两侧 SLO 同时恶化，整体 Goodput 按 $\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}}$ 计算会塌陷，因为分母（GPU 秒）不变而分子骤降。反过来，短请求突发会让 decode 池 batch 迅速填满、TPOT 抖动，prefill 池却闲着。这就是物理分离的结构性代价：混部时资源可以动态挪用，分离后挪用必须经过 KV 搬运这一跳，而搬运本身占用 RDMA 带宽，形成正反馈式的拥塞。</p>\n<p>第三个崩点是尾延迟与功耗的耦合。decode 池用 EP 承载大 batch 提升专家利用率，但 MoE 的 all-to-all 通信在 batch 增大时并不线性摊薄：每 token 的专家分发行数增加，NVLink 域内交换量上升，单 token 间隔的方差被放大。尾延迟（P99 TPOT）往往不是由平均带宽决定，而是由最慢的那个专家分片和一次 all-to-all 的排队决定。规模上去后，decode 池的 GPU 数增加意味着 EP 组扩大，跨节点 all-to-all 走 NVLink 5 与 NCCL 路径，通信跳数增加，尾延迟先于平均吞吐恶化。功耗侧同理：prefill 池在大 TP 下算力打满、功耗高但占空比随请求到达呈脉冲式；decode 池功耗平稳但基数大。两池分开后无法用一侧的闲置功耗预算去补贴另一侧的峰值，PUE 与机柜功率上限成为配比设计的硬约束，尤其在 NVL72 机柜内，单柜功率封顶会直接限制 $N_p/N_d$ 的可选范围。</p>\n<p>把这三者放进一张表看失效顺序，比看平均值有用：</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先恶化的指标</th><th>机制</th><th>工程应对</th></tr></thead><tbody><tr><td>上下文长度上升</td><td>TTFT</td><td>KV 传输字节线性增长，与计算未充分重叠</td><td>按层/页分块流水，格式与 EP 分片对齐</td></tr><tr><td>请求到达突发</td><td>Goodput 与双侧 SLO</td><td>静态配比失配，一侧排队一侧空闲</td><td>留缓冲 + 按队列深度触发比例微调</td></tr><tr><td>decode batch 增大</td><td>P99 TPOT</td><td>EP 组扩大，all-to-all 跳数与排队方差上升</td><td>限制单批 EP 跨度，分层聚合</td></tr><tr><td>机柜功率封顶</td><td>可选配比范围</td><td>两池功耗无法互相补贴</td><td>按功率预算反解 $N_p/N_d$ 上界</td></tr></tbody></table>\n<p>因此这套方案的适用边界是明确的：高负载、长上下文、TTFT 与 TPOT 双 SLO 严格且流量可预测的集群部署，收益最大；一旦流量形态不可预测或上下文长度分布尾部很重，静态配比与 RDMA 传输量就成为规模上限。判断是否该上的工程准则不是看平均吞吐，而是看三个量：KV 传输时间占 TTFT 预算的比例、突发时两侧队列深度的不对称度、以及 EP 组扩大后 P99 TPOT 相对 P50 的倍数。这三个量中任何一个越过预算，分离部署的收益就会被其管理复杂度与带宽开销抵消，此时应退回分块预填捎带或混部加动态切分。</p>\n<h3 id=\"alg-pd-disaggregation-moe-sec-40\">四十 · 精度漂移：跨池量化不一致与 KV 数值路径</h3>\n<p>分离部署把 prefill 与 decode 拆到两个 GPU 池后，量化方案可以各自独立选择——这是部署配方给出的自由度，也是精度问题的第一来源。prefill 池用大 TP 打满算力，倾向于激进的权重与激活量化以换取算力；decode 池用 EP 承载大 batch，倾向于保留更高精度的 KV 以稳定长序列。问题在于 KV 是跨池传递的物理载体：prefill 池按自己的数值格式生成 KV，经 RDMA 写入 decode 池的 KV 存储，decode 池按自己的注意力实现读取。若两侧对 KV 的缩放因子、分块粒度或累加精度约定不一致，误差不会在单池内暴露，而是在 decode 的第一个 token 上以 logits 偏移的形式出现，表现为输出重复、截断或语言漂移。</p>\n<p>诊断这类问题的关键是建立“数值契约”：KV 按层/页打包时，每一页携带自己的量化元数据（缩放因子、零点、块大小），decode 池接收时校验元数据版本而非假定格式。工程上把这条契约做成传输头的一部分，任何版本不匹配直接拒绝该页并回退到全精度重算，代价是一次额外的 prefill 计算，但避免了静默错误扩散到整段生成。</p>\n<div class=\"formula\">$$\\text{err}_{\\text{KV}}=\\left\\|\\,\\text{Attn}(Q,K_{\\text{prefill}},V_{\\text{prefill}})-\\text{Attn}(Q,K_{\\text{decode}},V_{\\text{decode}})\\,\\right\\|$$</div>\n<p>这个残差不需要每步计算，只在灰度发布或量化方案变更时对固定 prompt 集采样比对。系统代价上，全精度回退路径会让该请求的 TTFT 增加一次 prefill 时间，且占用 prefill 池算力；因此回退必须限流，按请求比例设阈值，超过阈值即判定为配置错误而非偶发。具体例子：长上下文请求在 decode 池出现首 token 后立即重复同一短语，检查发现 prefill 池以分块量化写 KV、decode 池按整页反量化读取，块边界处的缩放因子被错误复用——修复方式是统一块大小并在页头写入块数。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-41\">四十一 · OOM 的三条路径：KV 池、专家权重与传输缓冲</h3>\n<p>分离部署的显存账本比混部更复杂，因为 decode 池同时驻留三样东西：分页 KV、EP 分片后的专家权重、以及接收跨池 KV 的传输缓冲。OOM 因此有三条独立路径，诊断时必须先定位是哪一条，否则调参方向完全相反。</p>\n<ul>\n<li>KV 池溢出：decode 池连续批处理不断追加 KV，batch 越大、上下文越长，分页池越快耗尽。表现为新请求被拒绝或被迫抢占，TPOT 尖刺。</li>\n<li>专家权重挤占：decode 池按 EP 布局，单卡只驻留部分专家，但 router 与专家在同 rank，若专家分片数增加而单卡显存不变，权重占比上升会压缩 KV 可用页数。</li>\n<li>传输缓冲堆积：prefill 池向 decode 池 RDMA 写入时，接收侧需要暂存缓冲；当 decode 池忙于计算、写入速率超过消费速率，缓冲增长直至 OOM。</li>\n</ul>\n<p>监控上把这三项做成独立水位线而非一个总显存指标：KV 页占用率、专家权重常驻字节、传输缓冲队列深度。任一水位越过阈值即触发对应动作——KV 水位高则收紧连续批处理的最大 batch 或触发抢占；专家权重水位高则拒绝扩容 EP 分片；缓冲水位高则对 prefill 池施加背压，暂停新的 KV 推送。</p>\n<div class=\"formula\">$$B_{\\text{buf}}\\ge \\lambda_{\\text{prefill}}\\cdot \\bar{s}_{\\text{KV}}\\cdot \\tau_{\\text{drain}}$$</div>\n<p>其中 $\\lambda_{\\text{prefill}}$ 是 KV 到达速率，$\\bar{s}_{\\text{KV}}$ 是单请求平均 KV 字节，$\\tau_{\\text{drain}}$ 是 decode 侧消费一页的时间。缓冲必须按最坏到达速率配置，否则突发流量下先 OOM 再谈 SLO。具体例子：decode 池 batch 从稳定值突增，KV 消费变慢，缓冲在数十毫秒内填满，OOM 发生在 decode 计算线程而非传输线程，日志上看起来像“计算侧显存不足”，实际根因在背压缺失。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-42\">四十二 · 批抖动与路由不均：两个不同源的尾延迟</h3>\n<p>批抖动和路由不均都会表现为 TPOT 尖刺，但根因相反，混为一谈会修错地方。批抖动来自 decode 池的连续批处理：请求完成与到达不同步，batch 组成在时间上不均匀，某些迭代 batch 很大、某些很小，GPU 利用率随之波动，TPOT 的方差被放大。路由不均来自 MoE 本身：router 把 token 分配给专家时分布偏斜，某些 rank 上的专家过载、另一些空闲，EP 布局下这种偏斜直接转化为 all-to-all 通信的等待时间。</p>\n<p>区分方法看尖刺的周期性：批抖动与请求到达/完成节奏相关，尖刺出现在 batch 重组时刻；路由不均与输入内容相关，同一 prompt 反复出现尖刺而其他 prompt 平稳。监控上分别采集 batch size 的时间序列与每 rank 专家负载的基尼系数，前者高说明调度问题，后者高说明路由问题。</p>\n<div class=\"formula\">$$G=\\frac{\\sum_{i}\\sum_{j}\\left|x_i-x_j\\right|}{2n^2\\bar{x}},\\quad x_i=\\text{rank }i\\text{ 的专家 token 数}$$</div>\n<p>系统代价上，路由不均的代价是 all-to-all 的最慢 rank 决定整批延迟，即使平均负载不高，尾 rank 也会拖住 TPOT；批抖动的代价是算力空转，batch 小时 decode 池带宽利用率下降但延迟并未改善。具体例子：decode 池 TPOT 的 p99 出现规律性尖刺，间隔与请求完成速率一致，检查发现连续批处理在请求退出时立即重组 batch，重组瞬间新 batch 尚未填满，GPU 以半载运行一个迭代——修复是延迟重组到下一个调度窗口，用微小排队换取 batch 稳定。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-43\">四十三 · 尾延迟尖刺：RDMA 传输与重排的耦合</h3>\n<p>分离部署最特有的尾延迟来源是跨池 KV 传输。长上下文请求的 KV 传输时间不可忽略，若与 decode 计算未充分重叠，TTFT 被传输主导；更隐蔽的是层/页打包格式与 decode 池本地专家分片不一致时需要的额外重排，这部分显存拷贝发生在接收侧，与 decode 计算争抢带宽，尖刺出现在长上下文请求的首批 token 上。</p>\n<p>诊断需要把 TTFT 拆成三段：prefill 计算时间、KV 传输时间、decode 首 token 计算时间（含重排）。分别打点后，尖刺落在哪一段一目了然。若传输段占比高，检查 RDMA 带宽是否被其他流量挤占、流水重叠是否真的生效；若首 token 计算段占比高，检查重排路径是否走了不必要的显存拷贝。</p>\n<div class=\"formula\">$$\\text{TTFT}=T_{\\text{prefill}}+\\frac{S_{\\text{KV}}}{B_{\\text{RDMA}}}+T_{\\text{reorder}}+T_{\\text{decode,1st}}$$</div>\n<p>系统代价上，重排的代价是每层一次显存读写，层数越多越显著；流水重叠的收益是把传输时间藏进 prefill 后续层的计算里，但重叠要求 decode 池提前分配好接收页，否则退化为串行。具体例子：同一长上下文 prompt 的 TTFT 在 p50 正常、p99 翻倍，拆段后发现传输段稳定而重排段抖动，根因是 decode 池的接收页分配器在页池紧张时退化为同步等待——修复是预留接收页配额，把重排路径的分配从关键路径上摘除。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-44\">四十四 · 监控面与回滚：把两池当一条链路来观测</h3>\n<p>分离部署的监控不能按池各自为政，因为 SLO 是端到端的。观测面应沿数据流组织：prefill 池的排队与计算、KV 打包与 RDMA 写入、decode 池的接收与重排、连续批处理迭代、KV 释放。每个环节采集延迟分位数与吞吐，并用一个端到端 trace id 串起来，任何一段的尖刺都能定位到具体请求与具体层。</p>\n<p>关键指标包括：两池实际负载比与配置比 $\\frac{N_p}{N_d}$ 的偏离度（比例失配是一侧空闲一侧过载的直接信号）、RDMA 带宽利用率与重传、decode 池 batch size 方差、专家负载基尼系数、KV 页水位、传输缓冲深度。这些指标各自对应前四节的一种失败模式，形成一张诊断映射表。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>主指标</th><th>首查位置</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度漂移</td><td>固定 prompt 集输出比对残差</td><td>KV 页元数据版本</td><td>该请求全精度重算，回退量化配置</td></tr><tr><td>OOM</td><td>KV 页水位 / 缓冲深度</td><td>背压是否生效</td><td>收紧 batch 上限，对 prefill 池施压</td></tr><tr><td>批抖动</td><td>batch size 方差</td><td>调度重组时机</td><td>延迟重组，恢复上一调度窗口</td></tr><tr><td>路由不均</td><td>专家负载基尼系数</td><td>router 分布</td><td>回退路由配置或容量因子</td></tr><tr><td>尾延迟尖刺</td><td>TTFT 拆段占比</td><td>重排与传输重叠</td><td>预留接收页，回退流水配置</td></tr></tbody></table>\n<p>回滚的设计原则是分级而非一刀切。配置级回滚最快：量化方案、调度窗口、路由参数都是可热切换的配置项，回滚只需重载配置并让在途请求按旧路径完成。拓扑级回滚最慢：两池比例 $\\frac{N_p}{N_d}$ 的调整涉及 GPU 重新分配，代价是整池重启与 KV 清空，因此比例配置必须留缓冲，把拓扑回滚作为最后手段。工程判断上，任何一次灰度变更都应先在固定 prompt 集上跑精度比对与 TTFT 拆段，再放量；放量期间盯住比例偏离度与缓冲深度这两个先行指标，它们比 SLO 违约更早报警。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-45\">四十五 · 失效边界：比例失配、传输主导与布局重排</h3>\n<p>这套方案最脆弱的地方不在算子，而在两池配比被当成静态常量。按吞吐方程 $$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$ 配置后，一旦请求形态漂移——上下文变长、输出变短、或突发批量涌入——prefill 池与 decode 池就会一侧排队、一侧空转。此时 Goodput 的分母（总 GPU 秒）不变而分子（满足 SLO 的请求数）塌陷：prefill 侧 TTFT 超标，decode 侧 batch 填不满、专家利用率掉下来，两个 SLO 同时失守。诊断上要把两池的队列深度、SM 占用率与专家命中率分开看，任何一侧出现“高排队 + 低占用”的组合，就是比例失配而非单点故障，回滚手段是临时把空闲池的 GPU 划给过载侧（改 TP/EP 度或迁移实例），而不是调 batch 上限。</p>\n<p>第二个失效条件是 RDMA 传输把 TTFT 吃掉。KV 按层/页打包跨池搬运，传输量与层数、上下文长度、batch 成正比，而 decode 池的接收与本地专家分片必须对齐。若传输与 decode 计算没有充分流水重叠，首 token 时延就被传输主导，prefill 池算得再快也无意义。工程判断是：把“KV 传输耗时 / prefill 计算耗时”作为一个常驻比值监控，该比值随上下文增长而上升，接近 1 时说明分离部署已到规模上限，应缩短跨池链路或退回同池分块预填。传输层还要盯重传与拥塞，RDMA 带宽被长上下文请求挤占时，短请求的 TTFT 尖刺会先于平均值恶化。</p>\n<p>第三个是布局不一致带来的隐性拷贝。decode 池按 EP 布局接收 KV，router 与专家在本地 rank；若打包格式的层/页切分与本地专家分片不匹配，接收端必须额外重排，产生显存拷贝与延迟，且这部分开销不进任何“计算”指标，只在尾延迟上显形。监控应把重排字节数单列，与 KV 接收字节数对比；比例异常升高说明打包端与接收端的布局约定已经漂移，属于配置回归而非负载问题。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>回滚动作</th></tr></thead><tbody><tr><td>TTFT 尖刺、prefill 队列堆积</td><td>KV 传输未重叠或带宽被挤占</td><td>降上下文批次、启用传输流水</td></tr><tr><td>TPOT 抖动、decode batch 不满</td><td>两池比例失配</td><td>迁移 GPU 配额、重算 N_p/N_d</td></tr><tr><td>尾延迟抬升但均值正常</td><td>层/页打包与专家分片不一致</td><td>回退打包格式版本</td></tr></tbody></table>\n<p>精度问题在这套分离架构里通常不是数值本身，而是两池量化方案独立选择后 KV 语义不一致：prefill 侧写出的 KV 与 decode 侧期望的表示不匹配，表现为输出退化而非崩溃，最难定位。做法是把 KV 的 dtype 与量化档位写进请求元数据并在接收端校验，不匹配即拒绝而非静默转换；回滚以打包格式与量化档位为版本单位，一次只动一个维度。</p>\n<h3 id=\"alg-pd-disaggregation-moe-sec-46\">四十六 · 对照轴：三条正交的取舍线</h3>\n<p>把 MoE 预填解码分离（下称 PD 分离）放回同族算法里看，选型不是“谁更先进”，而是三条互相独立的取舍线：<strong>阶段是否物理隔离</strong>、<strong>并行策略是否按阶段解耦</strong>、<strong>KV 是否跨域搬运</strong>。分块预填与解码 piggyback 在单池内交错执行，第三条线取值为零，代价是 prefill 的大 TP 与 decode 的 EP 被迫在同一批 SM 上折中，router 与专家布局只能取一个双方都能接受的中间态；分离式专家并行把 EP 组跨节点拉大，解决的是专家权重放不下的问题，但两个阶段仍共享同一批 GPU，TTFT 与 TPOT 的争抢没有被消除；PD 分离则是唯一把三条线全部取“是”的方案，因此它同时拿到两个阶段各自的最优并行度，也同时背上 RDMA 传输与静态配比两项债务。</p>\n<p>判断一条工作负载该落在哪一格，先看一个比值：单请求 KV 字节数与单请求计算量之比。上下文越长、层数越多、KV 头维度越大，这个比值越高，跨池传输的相对代价越大；反过来，短上下文、高并发、decode 主导的负载，KV 传输量小，分离的收益几乎无成本地兑现。用公式表达选型的第一道门槛：</p>\n<div class=\"formula\">$$\\text{传输占比}=\\frac{V_{\\text{KV}}\\cdot N_{\\text{req}}}{B_{\\text{RDMA}}\\cdot T_{\\text{decode}}}$$</div>\n<p>其中 $V_{\\text{KV}}$ 为单请求 KV 字节数，$N_{\\text{req}}$ 为在途请求数，$B_{\\text{RDMA}}$ 为可用跨池带宽，$T_{\\text{decode}}$ 为该请求在 decode 池的驻留时间。该比值远小于 1 时，传输可与 decode 计算流水重叠而隐藏；接近或超过 1 时，TTFT 被传输主导，分离方案失去意义，应退回单池 piggyback。工程上这个量不需要精确测量，只需在长上下文样本上做一次端到端分解，看 TTFT 里传输段占多少。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-47\">四十七 · 决策表：五种形态的适用条件</h3>\n<p>下表把同族五种形态按触发条件排列，每一行给出“什么时候选它”和“什么时候别选它”。表中不写性能数字，只写判据，因为判据才是可复用的部分。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>选它的条件</th><th>别选它的条件</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>单池混部（基线）</td><td>流量低、SLO 宽松、上下文短</td><td>TTFT 与 TPOT 双 SLO 同时收紧</td><td>两阶段争抢 SM，SLO 只能保一个</td></tr>\n<tr><td>分块预填 + 解码 piggyback</td><td>单池、想改善 TTFT 尾延迟、不想引入跨池传输</td><td>decode batch 需要大而稳定以喂饱专家</td><td>prefill 块插入打断 decode 节奏，TPOT 抖动</td></tr>\n<tr><td>分离式专家并行</td><td>专家权重总量超出单节点显存，需跨节点 EP</td><td>瓶颈在阶段争抢而非显存容量</td><td>跨节点 all-to-all 通信占比上升</td></tr>\n<tr><td>PD 分离（本条目）</td><td>高负载、长上下文、双 SLO 严格、集群有富余 RDMA 带宽</td><td>上下文极长导致 KV 传输占比接近 1；流量突发且不可预测</td><td>跨池 KV 传输带宽 + 两池静态配比管理</td></tr>\n<tr><td>PD 分离 + 专家选择/容量因子路由</td><td>decode 池 EP 布局下专家负载倾斜明显</td><td>路由改动会破坏两池间 KV 布局一致性</td><td>路由决策与 KV 重排耦合，增加显存拷贝</td></tr>\n</tbody></table>\n<p>读表的方法是从上往下排除：先问单池能不能达标，能则停；再问瓶颈是显存还是争抢，是显存走分离式 EP，是争抢走 piggyback 或 PD 分离；最后问 KV 传输占比，占比高则 piggyback，占比低则 PD 分离。这条排除链的每一步都对应一个可观测指标——SLO 达标率、专家权重占用、TTFT 分解中的传输段——不需要凭直觉。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-48\">四十八 · 配比方程与选型的耦合</h3>\n<p>PD 分离一旦选定，第二个决策立刻出现：两池 GPU 数怎么分。吞吐方程给出静态解：</p>\n<div class=\"formula\">$$\\frac{N_p}{N_d}\\approx\\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</div>\n<p>这个比值不是常数，它随请求形态漂移。长上下文请求抬高 $R_{\\text{prefill}}$ 的单价（每请求算力），配比向 prefill 池倾斜；decode 侧 batch 增大提升 $R_{\\text{decode}}$，配比向 decode 池倾斜。选型时必须把配比的可调范围一起评估：如果流量预测误差大，配比需要留缓冲，缓冲本身是闲置 GPU，等于用容量换稳定性。这与 piggyback 形成直接对照——piggyback 没有配比问题，因为它只有一池，代价是两阶段在同一池内互相打断。所以选型的实质是：<strong>你愿意用多少闲置容量，换两个阶段各自的并行最优</strong>。</p>\n<p>具体例子：一个长上下文在线服务，prefill 池按 TTFT SLO 配大 TP，decode 池按 TPOT SLO 配 EP 与大 batch。假设流量预测显示 prefill 与 decode 处理能力之比为 1:2，则配比取 1:2 并留一档缓冲；突发流量到来时若 prefill 请求占比骤升，prefill 池先饱和，decode 池出现空闲，此时 TTFT 超标而 TPOT 反而变好——这种“单侧过载、单侧空闲”的非对称恶化是 PD 分离最典型的失败形态，也是选型时必须预判的。诊断方法是分别监控两池的队列深度与 SM 利用率，任一池队列持续增长而另一池利用率下降，即配比失配。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-49\">四十九 · 与量化、路由类算法的组合边界</h3>\n<p>PD 分离与量化方案是正交的：两池可独立选择精度，prefill 池算力密集可承受更高精度以保数值稳定，decode 池带宽密集倾向更低精度以省带宽。但组合有边界——若 decode 池采用 NVFP4 权重激活微缩放量化，KV 的打包格式与量化后的专家分片布局必须与 prefill 池产出的 KV 页格式对齐，否则 decode 池接收 KV 时需额外重排，增加显存拷贝与延迟。这条约束在选型表里体现为最后一行：路由类算法（专家选择、容量因子）改动专家分片布局，会与跨池 KV 布局耦合，组合前必须确认打包格式在两池间一致。</p>\n<p>与 MoE 投机解码的组合则更微妙：投机解码在 decode 池内增加 draft 计算，抬高 decode 池的算力需求，从而改变配比方程中的 $R_{\\text{decode}}$，配比需重新估算；同时 draft 模型与主模型的 KV 若都要跨池传输，传输量翻倍，传输占比公式中的 $V_{\\text{KV}}$ 需按两套 KV 计。因此“PD 分离 + 投机解码”不是简单叠加，而是要把投机带来的 decode 算力增量与 KV 增量一起代入配比与传输占比两道门槛，任一门槛不过则应拆掉其中一个。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-50\">五十 · 规模上限与退回路径</h3>\n<p>PD 分离的规模上限由 RDMA 带宽与 KV 传输量共同决定：上下文越长、层数越多，跨池传输越成为瓶颈。当传输占比逼近 1，系统的有效吞吐被 RDMA 带宽钉死，此时增加 GPU 数量只增加两池的闲置，不增加 goodput。判据是：</p>\n<div class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\quad \\text{约束}:\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$</div>\n<p>若传输段使 TTFT 越过 SLO，则分子塌缩，goodput 随规模下降——这是“加机器反而更慢”的机制解释。退回路径有两条：一是退回 piggyback，放弃阶段解耦换取零传输；二是保留分离但缩短跨池传输距离，把 prefill 与 decode 池放在同一 NVLink 域内，用更高带宽压低传输占比。两条路径的选择取决于瓶颈是带宽还是争抢：带宽瓶颈走第一条，争抢瓶颈走第二条。</p>\n<p>最终落在工程判断上：PD 分离的适用条件可以压缩成一句可执行的检查——在目标上下文长度上，KV 跨池传输时间能被 decode 计算完全重叠，且两池配比在预测误差范围内不出现单侧持续过载。两条同时成立则选它，任一不成立则退回同族中代价更低的形态；这个检查在部署前用一次端到端分解即可完成，不需要等到线上事故再回头改架构。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-51\">五十一 · 何时不该拆：物理分离的失效边界与选型决策</h3>\n<p>物理分离预填与解码不是普适解，它的收益严格绑定在“两阶段最优并行策略互斥”这一前提上。若模型是稠密结构、专家并行度为 1，prefill 的大 TP 与 decode 的大 batch 并不冲突，混部只需按时间片让路即可，拆池反而凭空引入一次跨池 KV 搬运。真正需要拆的是 MoE 且 EP 度较高、上下文又长的场景：此时 prefill 要的是把 GEMM 打满的大 TP，decode 要的是让 router 与专家留在本地 rank 的大 EP batch，混部只能折中，TTFT 与 TPOT 同时失守。判断标准可以写成一个比较式：设混部下的可行域为 $\\mathcal{F}_{\\text{col}}$，分离后为 $\\mathcal{F}_{\\text{dis}}$，只有当 $\\mathcal{F}_{\\text{dis}}$ 在双 SLO 约束下严格包含前者、且跨池传输开销未吃掉收益时才拆，即</p>\n<div class=\"formula\">$$\\text{Goodput}_{\\text{dis}}&gt;\\text{Goodput}_{\\text{col}}\\ \\Leftrightarrow\\ \\frac{T_{\\text{KV,xfer}}}{T_{\\text{decode,token}}}\\ll \\frac{N_d}{N_p}\\cdot\\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</div>\n<p>左端是单请求 KV 传输时间与单 token 解码时间的比值，右端是两池能力配比。上下文越长、层数越多，左端越大，拆池越不划算——这就是规模上限由 RDMA 带宽与 KV 传输量共同锁定的原因。工程上先把 KV 传输与 decode 计算做流水重叠，再测这个比值；重叠后仍不可忽略，就说明该请求形态已越过边界。</p>\n<p>与同族算法的取舍可以压成一张决策表。分块预填捎带（chunked prefill piggyback）在单池内把 prefill 切块插入 decode 批，省掉跨池搬运，但 decode batch 会被 prefill 块周期性打断，TPOT 出现抖动，适合中低负载、TPOT SLO 宽松的在线服务；连续批处理加优先级调度只在单池内做时间维度的隔离，不解决并行策略冲突，适合稠密模型；物理分离则把空间隔离做彻底，代价是 RDMA 带宽与静态配比管理。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>隔离维度</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody><tr><td>分块预填捎带</td><td>时间片</td><td>中低负载、TPOT 宽松、上下文中等</td><td>TPOT 抖动、prefill 块挤占 decode batch</td></tr><tr><td>单池优先级调度</td><td>时间片+优先级</td><td>稠密模型、EP 度低</td><td>不解决并行策略冲突</td></tr><tr><td>物理分离（本方案）</td><td>空间+并行策略</td><td>高负载、长上下文、双 SLO 严格、MoE 高 EP</td><td>跨池 KV RDMA 开销、两池静态配比</td></tr></tbody></table>\n<p>失效条件要逐条盯住。其一是配比失配：两池按 $\\frac{N_p}{N_d}\\approx\\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$ 静态配置，突发流量下必然一侧过载、另一侧 GPU 空闲，整体吞吐与 SLO 同时恶化，缓冲只能吸收预测误差、不能吸收形态突变。其二是长上下文传输主导：KV 按层/页打包经 RDMA 写入 decode 池，若与 decode 计算未充分重叠，TTFT 被传输而非计算决定，prefill 池算得再快也无意义。其三是格式不一致：decode 池按 EP 布局接收 KV 时，若层/页打包与本地专家分片不对齐，需额外重排，带来显存拷贝与延迟，这条在专家数多、分片细时最容易触发。其四是量化方案两池独立选择带来的数值一致性维护成本——两池可各自选位宽，但 KV 在跨池边界上必须同构，否则重排阶段还要做一次反量化。选型的最终判断落在流量形态上：请求长度分布稳定、可预测，拆池的静态配比才站得住；长度分布长尾重、突发性强，分块预填捎带的弹性反而更稳。</p>\n\n<h3 id=\"alg-pd-disaggregation-moe-sec-52\">五十二 · 同族对照下的选型判据与失效边界</h3>\n<p>与分块预填捎带（chunked prefill piggyback）相比，本方案的关键区别在于“物理分离”而非“时间片复用”：混部方案在同一 GPU 池上把 prefill 块插入 decode 批次，靠调度器切分 SM 时间，省掉跨池 KV 传输却把两阶段的并行策略锁死在同一拓扑上，MoE 的 router 与专家布局被迫折中；分离方案让 prefill 池用大 TP 打满算力、decode 池用 EP 承载大 batch，代价是 RDMA 上的 KV 搬运与两池静态配比。选型的量化入口是吞吐方程 <span class=\"formula\">$$\\frac{N_p}{N_d} \\approx \\frac{R_{\\text{prefill}}}{R_{\\text{decode}}}$$</span>，比例失配即一侧空闲一侧过载；再以 <span class=\"formula\">$$\\text{Goodput}=\\frac{\\text{满足 SLO 的请求数}}{\\text{总 GPU 秒}},\\ \\text{s.t.}\\ \\text{TTFT}\\le \\text{SLO}_{\\text{TTFT}},\\ \\text{TPOT}\\le \\text{SLO}_{\\text{TPOT}}$$</span> 作为统一裁判，任何方案只在双约束同时成立时计入收益。</p>\n<p>决策表按四个判据切分：负载强度与上下文长度、双 SLO 的严格程度、RDMA 带宽与 KV 传输量的比值、流量可预测性。<table class=\"mini\"><thead><tr><th>条件</th><th>分离部署</th><th>分块预填捎带</th></tr></thead><tbody><tr><td>高负载、长上下文、TTFT 与 TPOT 双严</td><td>优先，两阶段各取最优并行</td><td>受混部争抢，TPOT 抖动</td></tr><tr><td>KV 传输量相对 RDMA 带宽偏大</td><td>传输主导 TTFT，慎用</td><td>无跨池开销，占优</td></tr><tr><td>流量突发、预测偏差大</td><td>静态配比失配，需留缓冲</td><td>弹性更好，单池吸收</td></tr><tr><td>MoE 专家并行度高、decode batch 需大</td><td>EP 池稳定承载大 batch</td><td>专家布局被迫折中</td></tr></tbody></table>规模上限由 RDMA 带宽与 KV 传输量共同决定：上下文越长、层数越多，按层/页打包的 KV 体积越大，跨池传输越成为瓶颈。</p>\n<p>失效条件有三类。其一，两池比例按流量预测静态配置，突发流量下单侧过载、另一侧 GPU 空闲，吞吐与 SLO 同时恶化，缓冲只能吸收预测误差而不能消除。其二，长上下文请求的 KV 跨池 RDMA 传输时间不可忽略，若与 decode 计算未充分流水重叠，TTFT 被传输而非计算主导，此时分离方案的收益被传输开销吃掉。其三，decode 池按 EP 布局接收 KV 时，若层/页打包格式与本地专家分片不一致，需额外重排，增加显存拷贝与延迟——这一项在跨池协议设计阶段就要对齐，否则每次请求都付一次重排代价。工程判断是：先测 KV 传输时间与 prefill 计算时间的比值，再决定是否值得为并行策略自由度付出 RDMA 带宽；比值接近 1 时分离方案已无净收益。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · MoE推理KV cache压缩</td></tr><tr><td>解决什么</td><td>prefill 是计算密集、decode 是带宽密集，两者混部时资源争抢导致 TTFT 与 TPOT 无法同时满足 S…</td></tr><tr><td>一句话机制</td><td>把 prefill 与 decode 拆到不同 GPU 池，prefill 池用大 TP 打满算力，decode 池用…</td></tr><tr><td>代价与失效</td><td>KV 跨池传输占用 RDMA 带宽，长上下文时传输时间不可忽略；两池比例需按流量预测静态配置，突发流量下易出现一侧空闲一侧过载</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-pd-disaggregation-moe · 共 8 个片段</p>\n";break;}}})();
